#!/usr/bin/env node
import fs from 'fs';
import path from 'path';
import { fileURLToPath } from 'url';

const ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '../..');
const OUT = path.join(ROOT, 'output');
const BLOCK = '**** YD001 SOURCE BLOCK ****';
const ENG = '**** ENGLISH ****';
const END = '**** END BLOCK ****';

function patchFile(rel, slug, T) {
  const fp = path.join(OUT, rel);
  const s = fs.readFileSync(fp, 'utf8');
  const applied = new Set();
  const parts = s.split(BLOCK);
  const out = parts.map((block, i) => {
    if (i === 0) return block;
    const slugM = block.match(/^\s*slug: (.+)$/m);
    const seifM = block.match(/^\s*seif: (.+)$/m);
    const markerM = block.match(/^\s*marker: (.+)$/m);
    if (!slugM || slugM[1].trim() !== slug) return BLOCK + block;
    const seif = seifM[1].trim();
    const marker = markerM ? markerM[1].trim() : 'main';
    const key = `${seif}#${marker}`;
    if (!(key in T)) return BLOCK + block;
    const enStart = block.indexOf(ENG);
    const enEnd = block.indexOf(END);
    if (enStart < 0 || enEnd < 0) throw new Error(`ENGLISH/END missing: ${rel} ${key}`);
    const before = block.slice(0, enStart + ENG.length + 1);
    const after = block.slice(enEnd);
    const text = T[key].endsWith('\n') ? T[key] : T[key] + '\n';
    applied.add(key);
    return BLOCK + before + text + after;
  });
  const missing = Object.keys(T).filter((k) => !applied.has(k));
  if (missing.length) throw new Error(`Keys not found in ${rel}: ${missing.join(', ')}`);
  fs.writeFileSync(fp, out.join(''), 'utf8');
  console.log(`OK ${rel} (${applied.size} blocks)`);
}

// --- mechaber (20) ---
patchFile('siman_024/mechaber/part-001.txt', 'mechaber', {
  '1#main': `The laws of darsah, haladah, hagramah, and ikkur. In it are 20 seifim. Darsah — how so? Such as one who placed the knife on the neck and pressed and cut downward like cutting a radish or gourd — behold, this is invalid; and needless to say if he struck with the knife on the neck the way one strikes with a sword and cut the simanim in one motion.`,
  '2#main': `If he slaughtered with holacha or hava'ah alone — if the knife has the full width of a neck and beyond the neck the full width of a neck {Rama: (with the skin and spinal column) (Mahariu)} — it is kosher; and if not, invalid, for whenever it does not have this measure it is impossible to slaughter without darsah through holacha or hava'ah alone; and if he did both holacha and hava'ah, even if he slaughtered with any awl whatsoever, it is kosher. {Rama: And some are stringent in an animal (Mordechai and Ran in the name of Rabbenu Tam, and some say in Rif and it is mentioned in Agudah and Kol Bo and Hagahot Alfasi) and the custom in these provinces is to invalidate an animal even if he did holacha and hava'ah if the knife does not have somewhat beyond a full neck and beyond the neck (this is Mahariu's view).}`,
  '3#main': `If he slaughtered two heads as one with holacha or hava'ah alone — if the knife has the measure of three necks, it is kosher; and if not, there is concern and one should forbid both (Ramban, Rashba, Ran, and R' Yerucham).`,
  '4#main': `Two people hold the knife and slaughter — even if one is above toward the head and one below toward the chest, for they hold it diagonally — it is kosher, and we are not concerned lest they darsah one upon the other.`,
  '5#main': `If he was slaughtering and cut the entire spinal column — it is kosher {Rama: (Mordechai in the name of Maharam; see s.k. 5): And the custom is to declare treifah even if he only cut the majority of the spinal column (Mahariu, Agur, and Tur HaDeshen) and one should not deviate, for many authorities hold thus (Rabeinu Ephraim deduced from Rashi's explanation).}`,
  '6#main': `When a person slaughters a bird and holds the simanim with his two fingers, he must hold them well — for if he does not hold them properly, sometimes they slip here and there and he cannot slaughter them through holacha and will come to darsah. {Rama: And likewise he should not rest his finger on the knife but hold it in the handle so he does not come to darsah (his own view from slaughterers' practice and Maharshal, chapter HaShochet, siman 12):} And even if he did not do darsah but only something of the esophagus — invalid. {Rama: And the custom is to declare treifah any darsah, whether in the first minority, the last minority, in the trachea, or in the esophagus (shechitot of Mahariu).}`,
  '7#main': `Haladah — how so? Such as one who inserted the knife between one siman and another — whether he slaughtered the lower one properly from above downward and returned and withdrew it and slaughtered the upper one; whether he slaughtered the upper one from below upward not according to law — invalid.`,
  '8#main': `If he inserted the knife under the skin, or under tangled wool on the neck of the animal, or under a cloth tied on its neck, or the cloth is stuck to it with wax and he slaughtered — his slaughter is invalid; but if the cloth is spread on its neck and he slaughtered, his slaughter is kosher; and there is one who invalidates in this too, and l'chatchila one should heed his words. {Rama: And likewise one should be careful with sheep that have tangled wool on their necks to detach the tangled wool so he does not come to haladah (Mordechai, chapter HaShochet, and Rokeach).}`,
  '9#main': `One must be careful when a person slaughters and spares the skin not to make a large tear in it and slaughter at the head of the knife while it is covered by the skin; however, if he slaughters in the middle of the knife there is no concern if its head is covered by skin, since the knife in the place where he slaughters opposite the simanim is not covered; and there is one who is stringent in this too, and one should heed his words l'chatchila.`,
  '10#main': `If after he slaughtered the majority of the simanim he inserted the knife under the minority remaining of both or of one of them and paused — it is permitted; and there is one who forbids in this too, and it is fitting to heed his words l'chatchila. {Rama: And the custom is to declare treifah any haladah, whether in the first minority, the last minority, in the trachea, or in the esophagus (shechitah of Mahariu).}`,
  '11#main': `If he inserted the knife under the first minority and slaughtered it from below upward and afterward completed the shechitah in its proper manner; and likewise if he slaughtered the majority of one siman in an animal and inserted the knife under the remaining minority and slaughtered the second siman; and likewise if he slaughtered the first minority in haladah and completed the shechitah not in haladah — behold, this is invalid.`,
  '12#main': `Hagramah — how so? This one who slaughters on the trachea above in a place not fit for shechitah; or who began to slaughter in the place of shechitah and slaughtered a little and tilted the knife outside the place of shechitah upward and finished there — but if he slaughtered the majority of the cavity of the trachea in the place of shechitah and tilted the knife outside the place of shechitah upward and finished there the cutting of the entire trachea — it is kosher; and the same applies if he slaughtered the majority of two in an animal in the place of shechitah and completed the shechitah in hagramah or darsah — kosher; and there is one who invalidates in darsah, and one should heed his words l'chatchila. {Rama: And the custom is to declare treifah whether in darsah, hagramah, the first minority, the last minority, in the trachea, or in the esophagus (also in Mahariu).}`,
  '13#main': `If he did hagramah on the trachea at the beginning of a third and slaughtered two thirds — kosher. If he slaughtered a third and did hagramah on a third and returned and slaughtered the last third — kosher. If he did hagramah on a third and slaughtered a third and returned and did hagramah on the last third — behold, this is invalid; and if he darsahed or inserted haladah, whether in the first third or the middle third — behold, this is invalid.`,
  '14#main': `All these distinctions apply when it is certain he did not touch the esophagus but only the trachea on the upward side; but in the esophagus, even if he slaughtered in it any amount outside the place of shechitah, whether on the upward side or the downward side; and likewise on the trachea on the downward side before the fitness of shechitah was completed — even though he completed all the rest in the place of shechitah — behold, this is invalid because perforation of these places invalidates in any amount {Rama: (his own opinion and R' Yerucham) and the custom is to declare treifah in any case and one should not deviate (Mahariu).}`,
  '15#main': `Ikkur — how so? Such as the trachea or esophagus was uprooted from the jaw and from the flesh and one of them slipped out or both of them before the shechitah was completed; but if he slaughtered one in a bird or the majority of it and afterward the second slipped out — his shechitah is kosher; if one of them slipped out and afterward he slaughtered the second — his shechitah is invalid. {Rama: And we practice to declare treifah any ikkur, whether in the first minority, the last minority, in the trachea, or in the esophagus (according to Mahariu) and specifically after it was slaughtered; but while alive it is kosher, only shechitah does not permit it, and there is a practical difference regarding its milk or its eggs that they are kosher (Beit Yosef from Rashba's responsum).}`,
  '16#main': `That which is invalid in ikkur — this is when the whole was uprooted; but if something remained in it, even any amount — kosher, provided that which remained is in one place; but if the remaining minority is dangling — a little here and a little there — invalid, for it is evident the matter was uprooted by force and what remains connected is a dangling connection and it is as if the whole was uprooted and invalid. And this applies when the majority was uprooted; but if only a minority was uprooted and the majority remains, even though most of this remainder dangles a little here and a little there — kosher.`,
  '17#main': `If he slaughtered one of the simanim and the second is found dangling and it is unknown whether it slipped before shechitah or after shechitah — behold, this is invalid. {Rama: And even if he threw the bird from his hand, we do not say that because of the throw or convulsion it slipped (Maharik, shoresh 35); however, the slaughterer is believed to say it was not dangling at the time of shechitah (Piskei Maharai, siman 200).}`,
  '18#main': `If the slaughtered siman is found dangling — if when he slaughtered he grasped the simanim in his hand or the skin of the slaughter-house from behind it and the siman was pressed under the skin — behold, this is invalid; and if not, it is permitted through examination: he brings another animal and slaughters the siman and afterward uproots it — if the two slaughterings resemble each other, it is kosher; and if the second reddens more, the first is invalid; and now we are not expert in this examination — therefore in every case it is forbidden.`,
  '19#main': `If he slaughtered the bird in its proper manner with fitness and after completing shechitah found a whole ring from the crop on the knife — kosher. {Rama: And some declare treifah in this, and likewise ikkur (old shechitot in the name of Maharik, also according to his brother-in-law Mahar R' Yitzchak Katz who said thus practiced Mahar R' Moshe Yafeh) and one should not deviate.}`,
  '20#main': `One who slaughters a rooster must be careful to press its leg to the ground or raise them so its leg is not planted in the ground, so it does not uproot the simanim.`,
});

// --- siftei-kohen (31) ---
patchFile('siman_024/siftei-kohen/part-001.txt', 'siftei-kohen', {
  '2#_': `If there is in the knife, etc. See above siman 8 what is written on this.`,
  '3#א': `[<b>If he slaughtered two heads, etc.</b> It appears that b'dieved alone is meant; and in Tur it states "a person slaughters two heads as one," etc., and so it is stated explicitly in the Gemara, chapter HaShochet (Chullin daf 29a), and so too Ran — permitted even l'chatchila; and one must say "slaughtered" is not precise, for the same applies even l'chatchila; and so one must say from Rambam, chapter 2 of Hilchot Shechitah, law 9, and Kol Bo — see there and understand.]`,
  '3#ב': `[<b>If there is in the knife the measure of three necks, kosher.</b> Explanation: whether he placed the knife at the beginning of shechitah on the width of both heads and the length of the knife extended a full neck beyond both heads and he drew the knife to the other side until nothing remained protruding on that side already; or whether he began to slaughter at the edge of the knife and drew the knife in his slaughter until a full neck extended beyond the second head — then certainly, since on both heads he passed a full two necks, kosher; but plainly, if he placed the knife at the beginning of shechitah on the width of both heads and drew the knife to that side that already protruded beyond both heads a full neck — this is considered as if the knife has only the measure of two necks, and understand.]`,
  '3#ג': `[<b>And if not, there is concern.</b> This is the view of Ramban, Rashba, and Ran (see in Rashba's chiddushim daf 32a and Tur HaDeshen daf 27b); and it appears to me they deal when he placed the knife at the beginning of shechitah on the width of both heads and deal when he slaughtered toward the side that protruded — and Beit Yosef and Darkei Moshe wrote according to their reasoning: since we see that in one of them he darsahed, therefore in the second too he darsahed, for behold in one act and one matter he passed the knife over both; the same applies when he began to slaughter at the edge of the knife — since half the knife passed over the second, they rule both are forbidden for this reason: at least our eyes see one was darsahed, and if so in one act he passed the knife over both, and if so the second too was darsahed; and so appears Maharshal, chapter HaShochet, siman 11 — not like Bach who distinguished between beginning at the edge of the knife and placing the knife at the beginning on the width of the heads in matters not acceptable to the heart; and it also appears to me: if he began at the edge of the knife and passed the knife to the other side until a full neck protruded on the other side in a manner that the entire knife passed over both — both are kosher according to all, and so wrote Beit Yosef, Darkei Moshe, and Maharshal, and it is simple — not like Bach who distinguished on this; and his words are not seen either in the substance of the matter or in Ra'osh's words — examine well.]`,
  '5#_': `And the custom is to declare treifah, etc. And study is needed on this, for many great poskim permit — behold they are Mordechai and Agudah, chapter HaShochet, in the name of Maharam, and Ramban and Ran, chapter HaShochet, on the mishnah "he was slaughtering and removed the head," etc.; and so Rashba wrote in the name of great commentators; and so Ra'ah in Bedek HaBayit (daf 23); and so appears Rambam, chapter 2 of Hilchot Shechitah, law 9, as explained in Kesef Mishneh there; and so in Ba'al HaItur; and so Rashba in his chiddushim and Tur HaDeshen and Maharshal, beginning of siman 2; and so appears in Tosafot, chapter HaShochet, s.v. vetu; and so appears in responsum of Binyamin Ze'ev, siman 327; and so is proven from the mishnah and sugya, chapter 1 of Chullin (daf 19b), and the tosefta Mordechai brought, chapter HaShochet — see there and understand; and so is proven from all the poskim; and Taz in siman 21 also in Tur HaDeshen, siman 187, wrote that by law it is permitted, only they practiced to be stringent; and so appears in Agur, who concluded "but most poskim permit" — accordingly; and perhaps Rabeinu Bechor's view is specifically to be stringent where there is no great loss; and in such a case.`,
  '7#_': `Whether he slaughtered, etc. — and all the more so if he inserted the knife under both simanim and slaughtered them from below upward, or slaughtered the lower from below upward and the upper properly — this is haladah.`,
  '8#א': `[<b>His slaughter is invalid.</b> All this is doubt of invalidity, for they were unresolved and not clarified.]`,
  '8#ב': `[<b>And likewise one should be careful, etc.</b> And in Mordechai he concluded that in birds too one should pluck feathers from them; and so in Atzei Erez; and Ba'er Heitev relied on what he wrote in siman 23: l'chatchila one should not pluck if he can slaughter without this — and automatically it is understood: whenever he cannot slaughter without this, he may pluck.]`,
  '9#_': `And one should heed his words l'chatchila — meaning in this, that where he slaughters it is exposed; but in the first law, when he slaughters at the head of the knife and the knife in the place of slaughter is covered by skin — it appears from the Mechaber that even b'dieved it is invalid; and so appears in Beit Yosef; and Atzei Erez wrote one must be careful not to insert the knife at the time of shechitah under the skin in any place, whether opposite the simanim or opposite the knife not opposite the simanim — end; and he did not explain well: at the beginning b'dieved invalid, and Bach challenged the Mechaber from Tosafot and Hagahot Ashiri who forbade even b'dieved — and I do not understand his challenge, for one may say Tosafot deal when the knife in the place he slaughters is covered, and in Hagahot Alfasi explicitly on this — see there; and see Maharshal, chapter 1 of Chullin, siman 42.`,
  '11#א': `[<b>If he inserted the knife, etc.</b> All the laws in this seif are explanations of the unresolved matter "he inserted in a minority of simanim — what is the law?" — and it was not clarified, and we rule stringently and it is doubt of neveilah.]`,
  '11#ב': `[<b>And slaughtered it from below upward, etc.</b> Bach wrote: one must explain accordingly that before he inserted he cut the skin and inserted afterward under the first minority of the siman — otherwise it is under the skin and in any case invalid; and so Tosafot and Ra'osh according to Rabbenu Tam, who also explains insertion under the first minority — end; and I did not descend to the end of his view, for certainly according to Rabbenu Tam, who explains insertion under the first minority and slaughters again all the simanim in haladah, it must be so; but in this law, where he only slaughters the minority in haladah and completes shechitah not in haladah — likewise it would be under the skin; and from the unresolved matter whether haladah applies in a minority of simanim, or we say since he completed shechitah not in haladah it is kosher.]`,
  '11#ג': `[<b>And likewise if he slaughtered the majority of one siman in an animal, etc.</b> But in a bird, once one siman was slaughtered it is fit and haladah no longer invalidates — so all poskim; and see above siman 23, s.k. 9.]`,
  '11#ד': `[<b>And likewise if he slaughtered the first minority in haladah, etc.</b> The esophagus is meant — for in the trachea it is not forbidden because of haladah in the first minority, like half a defective trachea, as in the Gemara and poskim; and Taz, siman 21, and siman 23, seif 5; and so in Derishah. Bach wrote in seif 8: and I found Maharshal who wrote — and since Tur wrote there are those who forbid hagramah on a third and slaughter two thirds, all the more one should forbid shehiyah or haladah in the first minority, even in the trachea; otherwise one would say the same regarding hagramah on a third and slaughter two thirds; on the contrary I would say: even one who disagrees and holds kosher when he did hagramah on a third and slaughtered two thirds, since it is not the place of shechitah, nevertheless agrees regarding shehiyah or haladah, for what difference is there between the last minority, where everything was already slaughtered properly and nevertheless we forbid because it became like a disqualification in shechitah — all the more in the first minority — end; and these are clear words, not like Maharuch, who wrote that in the first minority of the trachea it is not forbidden because of haladah and permits from Maran — end Bach; and in truth I found thus in Hagahot Maharshal on Tur; but I wonder: if they wrote "is there one who says shehiyah in the first minority of the trachea is invalid?" — behold the sugya is arranged, chapter HaShochet (Chullin daf 28a): half the crop was slaughtered and he paused the time of shechitah and completed — kosher; and Rambam, chapter 3 of Hilchot Shechitah, law 6: if he slaughtered the trachea alone, half or a minority, and paused a long time — he returns and completes shechitah and there is nothing in it — end; and it is simple and agreed among all poskim, as explained above siman 23; and even those who forbid hagramah on a third and slaughter two thirds — Rashba explicitly permits shehiyah in the first minority of the trachea, and the reason hagramah alone is invalid is because at the time life departs (meaning when slaughtering the middle third the majority was slaughtered) there is no majority in the place of shechitah, unlike shehiyah and haladah, which are kosher according to all; and so appears in Tosafot daf 30b, s.v. hachalid, and Ra'osh there and other poskim; and Ribash, siman 187, explicitly according to Rambam — these the Mechaber cited deal with the esophagus, that in the trachea haladah in the first minority is kosher — see there; and in chapter HaShochet (Chullin daf 32b) it is proven explicitly that haladah is no worse than the mishnah of the crop, and we rule below siman 34 that it is treifah only in the majority; and therefore what is found there from Maharshal is for us, who are stringent in hagramah in the first minority — and the same in all laws of shechitah — from concern we are not expert in examining the esophagus and we fear he touched the esophagus, as above siman 23; but certainly by law and according to the poskim and Rambam, shehiyah and haladah in the first minority of the trachea are kosher, as Derishah wrote.]`,
  '12#א': `[<b>Majority of the cavity of the trachea.</b> But in the majority of the rings it does not suffice, for they do not surround the entire trachea; and even if he slaughtered the majority, he still did not slaughter the majority of the trachea except for the upper ring that surrounds the entire trachea — Tur; and see above siman 20.]`,
  '12#ב': `[<b>And there is one who invalidates in darsah.</b> But in hagramah he validates, for since hagramah is not the place of shechitah, it is as if he drew with his hand or foot after shechitah — Tosafot, Ra'osh, and other poskim.]`,
  '13#א': `[<b>And slaughtered two thirds, kosher.</b> The reason: there is majority in shechitah; and likewise if he slaughtered a third, did hagramah on a third, and slaughtered a third — kosher for this reason.]`,
  '13#ב': `[<b>Behold, this is invalid.</b> For there is majority in hagramah.]`,
  '13#ג': `[<b>And if he darsahed or inserted, etc.</b> Know that the entire seif is the language of Rambam, chapter 3 of Hilchot Shechitah; and Ribash in responsum 187, R' Yosef ibn Shooshan, and Kesef Mishneh were entangled in his explanation, for it was difficult for them: he wrote that haladah in the first third is certainly invalid, yet earlier wrote that if he slaughtered a minority of simanim in haladah and completed not in haladah — doubt of neveilah (as in s.k. 11); and what connection does darsah or haladah in the first or middle third have to what he wrote here regarding hagramah? Ribash was lengthy in resolving it and concluded Rambam's words are incorrect and hard to fit. Kesef Mishneh brought responsum of R' Yosef ibn Shooshan, who was lengthy and rejected all Ribash's words and intended one matter with Kesef Mishneh: Rambam's words "if he darsahed or inserted in the first third — invalid" mean: if he darsahed or inserted the first third and slaughtered properly the second third and darsahed or inserted the third third; and likewise if he slaughtered the first third and darsahed or inserted the middle third and slaughtered properly the last third — certainly neveilah, for we would not think that just as with hagramah, slaughter a third, hagramah a third, slaughter a third is kosher, so too with darsah and haladah — therefore he said there is no case of insert a third, slaughter a third, insert a third; in such a case even with hagramah it is invalid; and likewise all is invalid in darsah and haladah, for hagramah is not in the place of shechitah; therefore when he slaughtered the first and last thirds in the place of shechitah, he slaughtered two thirds in their place — what do we care about the middle that he did hagramah? But haladah and darsah, which are in the place of shechitah in the middle, also invalidate; but if he slaughtered a minority of simanim in haladah and completed properly — we are in doubt, therefore he ruled doubt of neveilah — end; therefore the Mechaber cited Rambam's language whether in the first third or the middle third without the letter hei; and all their words are very forced and not seen at all, as the knowledgeable know; and what can I do — in my humble opinion Rambam's words are simple; therefore he was precise in his concise language: "and if he darsahed or inserted, whether in the first third or the middle third" with the letter hei — and it refers to what he wrote: hagramah on a third and slaughter two thirds, or slaughter a third, hagramah a third, slaughter a third — kosher; and he said: do not think that since with hagramah on one third it is kosher, likewise if he darsahed or inserted the first or middle third it would be kosher; for since hagramah is not in the place of shechitah we do not count it at all — and if so it is as if he darsahed or inserted in the first minority; he teaches it is not so; and therefore he said: "and if he darsahed or inserted in the first third" — meaning not slaughter a third, hagramah a third, slaughter a third, but darsahed or inserted a third, hagramah a third, slaughter a third; or in the middle third — meaning not hagramah a third and slaughter two thirds, but hagramah a third, darsahed or inserted a third, slaughter a third — his shechitah is invalid; for we require majority in shechitah specifically; and now Rambam deals properly with the trachea, therefore it is certainly invalid — and this is clear to me.]`,
  '14#א': `[<b>And likewise on the trachea downward.</b> For its perforation invalidates in any amount, as below siman 34.]`,
  '14#ב': `[<b>Behold, this is invalid.</b> It implies certainly invalid; and although haladah in the first minority of the esophagus is doubt of neveilah, as above s.k. 11 — there the reason, as Ribash wrote, is since it is in the manner of shechitah one may say it is not a perforation, for thus the Merciful One taught Moses not to slaughter the majority in haladah, but the minority is permitted; but hagramah, since it is not in the place of shechitah, is a perforation. And the rest of the laws of hagramah were explained in siman 20 — see there.]`,
  '15#א': `[<b>From the jaw and from the flesh, etc.</b> But if the flesh tore off with the simanim, even if all were uprooted — he holds it is kosher.]`,
  '15#ב': `[<b>One of them slipped out, etc.</b> For although a bird is fit with one siman, nevertheless we require both to be fit for shechitah — Rashba.]`,
  '15#ג': `[<b>And we practice to declare treifah any ikkur, etc.</b> Explanation: from what appears the Mechaber holds that even ikkur at the time of shechitah is not invalid except when uprooted before completing the majority of its shechitah — in this we practice to declare treifah any ikkur, even any amount (meaning by force of custom, but by law it is kosher, as Ran and poskim, and so appears in Tur — not like Bach, who wrote Tur deals when it slipped before shechitah — see there and understand) whether he slaughtered the first minority and it was uprooted even any amount at the time of shechitah, or in the last minority, trachea, or esophagus — since a disqualification occurred in shechitah, we practice to declare treifah everything from concern lest the esophagus was perforated, as above siman 23 and siman 34 regarding crop severance, and in several places; but if it slipped before shechitah, we establish it according to law (so in shechitot of R' Tzvi and other latter shechitot, and so Bach) — for the Mechaber, only when all were uprooted from the flesh in the jaw, or the majority and the minority remained dangling, is it ikkur; and what Ba'er Heitev wrote "and specifically, etc." refers where even by law the animal is forbidden — nevertheless its milk is kosher; and it appears from Ba'er Heitev that even if the majority dangled while alive, its milk or eggs are kosher — so Rashba in Tur HaDeshen and Beit Yosef brings it; however, although so appears from Tur and Ramban whom Ran brings, chapter 1 of Chullin — nevertheless Tosafot, chapter Eizehu Mekoman (daf 44), s.v. vehai ika ikkur, hold that if the majority dangled it is actual treifah even while alive; and so appears Rif and Rambam, and Rashi daf 43a, as in siman 29, s.k. 9; and so Ra'ah in Bedek HaBayit daf 23; and so is proven in the sugya daf 42b regarding what they challenged there — see there.]`,
  '15#ד': `[<b>Only shechitah does not permit it.</b> Because due to ikkur the simanim sway and it is impossible to slaughter them properly — Ran in the name of Ramban.]`,
  '16#_': `But if the remaining minority, etc. The reason Rashba wrote: when it comes apart in many places, the matter is evident it was torn by force; and what remains connected is a dangling connection; but when torn in one place, that minority remains in its original strength — therefore it is a connection and returns healthy — end; and Beit Yosef and Darkei Moshe bring it.`,
  '17#א': `[<b>If he slaughtered one of the simanim, etc.</b> It deals with a bird — understand.]`,
  '17#ב': `[<b>Behold, this is invalid.</b> Explanation: doubt of neveilah — and it is simple.]`,
  '17#ג': `[<b>And we do not say that because of the throw, etc.</b> See below siman 25, s.k. 4.]`,
  '18#א': `[<b>Behold, this is invalid.</b> For since he grasped the simanim, it is possible it was dangling, was slaughtered, and possible it slipped before shechitah — and it is doubt of neveilah.]`,
  '18#ב': `[<b>He brings another animal and slaughters, etc.</b> And the same applies: he brings another animal and uproots it and slaughters — if the first reddens more, kosher; if not, invalid; and that inversion on that siman itself does not help, as below siman 34 regarding crop severance — for here, since it is dangling it is not treifah, therefore the siman is considered alive; and even if it slipped before shechitah, the prior cut reddens more than the cut after shechitah — Tosafot, chapter Eizehu Mekoman, daf 54a.]`,
  '19#_': `And likewise ikkur. And in responsum of She'erit Yosef, siman 47, he was in doubt if found on the ground; and so Bach — even if the ring is found on the ground, even if the ring was cut on one side, it is doubt in shechitah and invalid — not like at the end of responsum of Ma'aseh Binyamin, who permitted if found on the ground; and see siman 34, s.k. 16.`,
});

// --- turei-zahav (18) ---
patchFile('siman_024/turei-zahav/part-001.txt', 'turei-zahav', {
  '3#_': `And forbid both. Tur in the name of Ra'osh wrote on this: if he drew and did not bring — the outer is kosher and the inner invalid; if he brought and did not draw — the inner is kosher and the outer invalid. Beit Yosef explained: in "drew and did not bring" — the inner is invalid because only half the knife passed over it; and he rules: when the knife head reaches the outer one; and likewise if he did not pause and also brought over the inner the entire knife length — it is kosher; only he stated the ordinary way; and likewise the reverse in "brought and did not draw." And in Perishah on this: it is forced to explain thus — who would say this is the ordinary way? And he brings another explanation in the name of R' Nissim: inner means the outer from the wall, etc. — more forced to explain thus; and Maharshal explained: specifically when he began at the knife edge by the handle — then when he slaughtered the outer a full neck and began to bring the knife on the inner, he must necessarily also bring the knife on the outer again to slaughter it, for while the knife had not yet passed over the inner he only slaughtered the outer a full neck, etc. — end; and it is difficult: what concern do we have with knife length of two necks — also with three there is this concern; if we see that when the outer neck was cut the inner was cut equally, and he began on the outer, therefore the inner was darsahed, for it has no measure like the outer; if not, why would it need even a small part of the outer? In my humble opinion Maharshal's reasoning is certainly true when slaughtered equally — only we must explain the tanna's wording differently: "slaughtered two heads as one" implies finishing shechitah truly equally with no precedence of one over the other — if there were precedence it would be called one after the other; rather as I explained; and the tanna's intent is to teach that what is inside the neck does not count until he passes beyond it — behold if the knife is long as three necks we find this properly: he leaves the measure of two necks on both necks, and when he brings automatically beginning and end are equal for both, for on each neck there is a corresponding part; and when he brings one neck's length, inside each neck one neck's length remains and at once both are slaughtered truly equally and both kosher; but if the knife is only two necks, one cannot say in any way their slaughter finishes equally and both kosher unless he places the knife's length on both necks and slaughters on each what is on it — both invalid, for each was slaughtered only one neck's measure; and likewise one cannot say the inner is kosher because he passes the entire knife over it — for then finishing both equally is not so, for the outer was slaughtered before it; rather one must find he places the side by the handle on the outer lip — automatically the outer has two full necks; and when he cuts two necks' measure he reaches the inner one neck's measure, for its slaughter finishes at exactly the same moment with the outer — therefore only the outer is fit and the inner was darsahed, for it had only one neck's measure; and likewise the reverse if he brought, etc. — to explain in my humble opinion the plain meaning with good reasoning (♯) except for practical halakhah Shulchan Aruch ruled like Rashba: since we saw one was darsahed, we say the second too was darsahed even if it had measure.`,
  '5#_': `Majority of the spinal column. In Mordechai, Rabeinu Ephraim deduced from Rashi's explanation on the mishnah at the beginning of chapter HaShochet on "we do not make it a block" — he removed its blood and no more; and Maharam's view: this "no more" of Rashi means he need not slaughter more; and in my humble opinion Rabeinu Ephraim's view is wondrous, for the mishnah on slaughtering from the nape implies if he cut the spinal column before slaughtering the simanim it is treifah — it implies after the simanim there is no concern at all; and so in Derishah, siman 1, he brought proofs from other poskim; and in Tur HaDeshen, siman 187, he wrote this prohibition is only a mere stringency; and I found Mahar R' Leib of Prague who permitted in practice cutting the entire spinal column after the simanim; and so appears the essence — only since Rama wrote one should not deviate from custom to declare treifah even in majority of spinal column, we cannot be lenient except in permitted matters others practiced as forbidden; nevertheless one should be lenient in all doubts — even if one sees a cut in the spinal column, one need not check whether it is majority or not; and all the more if the spinal column is not before us in all of them one may rely to be lenient; and one should not be stringent except if they already saw majority of spinal column was slaughtered, true majority, not in another matter; and this majority of spinal column — in my humble opinion the essence depends on the cord, for even according to Rabeinu Ephraim who explains Rashi's "no more" forbids cutting afterward — he was particular only about the cord life depends on; and on this the Torah said the animal should die only through the simanim, not otherwise — otherwise one would say he should not cut anything after the simanim; rather certainly as I explained; and it is fitting to rely to be lenient, since this treifah is only a stringency. After writing this I saw in Tur HaDeshen daf 23: "we do not make it a block" means only where blood flows — the simanim — but he should not break the spinal column, for if he broke the spinal column before the soul departs, blood is absorbed in the limbs and it is forbidden, as we say in chapter Kol HaBasar — end; and Bedek HaBayit disagrees and wrote there is concern only through breaking, not through cutting at the time of shechitah; and in Mishmeret HaBayit he strengthened Rashba's words and rejected Bedek HaBayit — see there; and I will not enter to decide between them (♯) but I greatly wondered if these words came from Rashba himself, for he himself cites in chapter 25 "and absorbs blood in the limbs and forbidden to eat raw, but through salting permitted," as Taz, siman 67, wrote; and Beit Yosef wrote Rashba said likewise in Tur HaDeshen daf 67 — if so, one cannot explain this is as if not slaughtered and forbidden even through salting; therefore this explanation is not the essence and Bedek HaBayit's words are true at least as we rule — in my humble opinion.`,
  '7#_': `Haladah — it is the language of hiding; therefore it is called chuldah (weasel) in this language, for it hides itself in the earth — so in the Gemara, chapter 1 of Chullin (daf 20).`,
  '8#_': `And there is one who invalidates in this too. This is Rambam's view in Tur (♯) and it is difficult from Talmud Yerushalmi that it is not so, for in chapter Behemah HaMekasheh (Chullin daf 74) Rav Oshaya asked: he put his hand into the animal's womb and slaughtered a nine-month fetus alive — what is the law? And why do we not forbid from haladah, for the knife is not exposed? Rather haladah applies only to what is tied on its neck; and Levush erred in this in siman 14, as written there.`,
  '9#_': `And one should heed his words l'chatchila. Maharshal disagrees with this ruling because Tosafot, chapter 1 of Chullin (daf 20), in the name of Rashi, chapter Chatas HaOf, wrote: when the knife head is covered — it is haladah; therefore forbid even b'dieved — end; and from this there is no grasping: there it deals when he also slaughters the simanim at the knife head, and there deals with melikah with a knife and he must be careful not to cut the spinal column with majority flesh upon it, as I cited siman 20, seif 3 — therefore he must plant the knife head under the flesh on the spinal column so it remains, and below he cuts at the knife head the spinal column with the simanim — behold at the place of slaughter the knife is covered; and so explicitly in Hagahot Ashiri, beginning of chapter 1 of Chullin, as written; and so in Rokeach, laws of shechitah; but this law does not deal there at all.`,
  '11#_': `And likewise if he slaughtered the first minority in haladah. Explanation: under the skin, and he slaughtered the first minority from above downward, and afterward slaughtered the rest not in haladah — this is what he adds to the first division, where it is worse: he slaughtered the first minority from below upward.`,
  '12#_': `And finished there cutting the entire trachea — kosher. In Tur it is written: even for one who forbids shehiyah and haladah in the last minority — the reason here is he does not make invalid in the place of shechitah, for what he cuts afterward in the minority of the trachea is as if cutting with the foot after slaughtering the majority of the siman in a bird or after majority of two in an animal.`,
  '15#א': `From the jaw and from the flesh. It implies if flesh is still on the simanim it is kosher; and so Beit Yosef in the name of Rashba explicitly; but in Tur it implies treifah for anything slipped from the jaw; and so appears in Ashiri, who did not bring the resolution in the Gemara of agam agumim.`,
  '15#ב': `And one of them slipped out. In Tur it is written: the siman was uprooted or slipped, etc. — its explanation: uprooted means by human force; slipped means by the animal's own motion.`,
  '15#ג': `But while alive it is kosher, etc. They proved this in Tosafot, chapter 1 (daf 9), from the challenge they raised: it is obvious shechitah does not help since it was already treifah — rather certainly it did not become treifah because of this ikkur, only halacha to Moses from Sinai that shechitah does not permit it until here; and they answered Rashba: even though a bird is fit with one siman, nevertheless we require both fit for shechitah; and they answered from the Gemara, chapter Behemah HaMekasheh (Chullin daf 69), in the question of milk of a ben pekua, etc. — as I brought siman 14, seif 8: here regarding ikkur there is no remedy through shechitah; nevertheless the milk is permitted, for there they only said the prohibition of eiver min hachai is lighter than yotzei, since remedy can apply to that prohibition sometime, unlike yotzei which has no remedy at all.`,
  '16#א': `That which is invalid in ikkur, etc. It implies explicitly that even at the time of shechitah we do not forbid ikkur of a dangling siman except when the whole was uprooted — for in the prior seif he wrote it happened before completing shechitah, automatically ikkur occurred at the beginning of shechitah; and on this he says in this seif: kosher if any amount remained, with no distinction between during shechitah or before shechitah; and no posek divides on this, and there is no reason to divide — for since the majority was not uprooted there is no treifah, why forbid because it happened at shechitah? And so is proven explicitly from Tosafot I cited, who challenged: it is obvious shechitah does not help; and they further challenged: what connection does this ikkur have to laws of shechitah? etc. — and they had to resolve it deals when the siman slipped and afterward he slaughtered it — end; and if you say at the time of shechitah it is stricter and forbids ikkur there even without the whole uprooted, only part — they would not have challenged at all, for there is a great difference between at shechitah and before shechitah; rather it is clear that even ikkur at shechitah is not forbidden except in the whole, as in this seif; and so is explained in Ran in the name of Ramban whom Beit Yosef brings: ikkur means simanim uprooted entirely or majority in a matter making treifah — and it should have said if this happened at shechitah it would be neveilah, since once it slipped at that time it is impossible to slaughter properly, for due to ikkur the simanim sway — end; and it is simple that also when this ikkur happened before shechitah it is treifah — the mishnah is crop severance; nevertheless it is not neveilah until it is so at shechitah; and so Beit Yosef — behold in any case there is no stringency even at shechitah except when all or majority were uprooted; and I wrote this because Maharshal wrote: it appears to me if ikkur happened at shechitah he forbids even in any amount uprooted, and we do not require the whole or majority, only if before shechitah; and he wrote he found thus, and so Semak and Mahariu did not mention measure in this ikkur (♯) and I know no place for this stringency, for all early and late authorities who did not write measure wrote "the simanim were uprooted" — meaning all simanim; only in Hagahot shechitot of Mahariu he wrote: at shechitah he forbids even in a minority; and perhaps on this Maharshal hinted in "I found thus"; but the essence is that even at shechitah ikkur forbids only in the whole; and the author of Hagahot shechitot did not write well on this, and so in Sefer Zivchei Riv.`,
  '16#ב': `A little here — invalid. They told him: behold at the beginning he wrote if something remained — kosher; here, when torn in many places it is evident it was torn by force and what remains is a dangling connection; but at the beginning, when torn in one place, that minority remained in its original strength — so Rashba.`,
  '17#א': `Behold, this is invalid. And Maharik concluded there: and they told him — if it had been dangling beforehand, he would have seen or felt it, for who can distinguish this? — it is like bones in a full belly — end.`,
  '17#ב': `However, the slaughterer is believed, etc. At first glance this contradicts what Maharik wrote above, that one cannot know at shechitah; here it deals where after shechitah in the place of slaughter a change is seen from what it was at shechitah — the uprooted place turned over and came there; with this he is believed to say it was not so at shechitah, and we must say it happened afterward through convulsion; unlike above, where nothing of uprooting is seen at the place of slaughter, only above at their connection in the jaw, still covered in skin — certainly he cannot distinguish this.`,
  '18#א': `Behold, this is invalid. Because then it is possible it was already dangling and he slaughtered it afterward, since he grasped the simanim; and Rashal wrote: nowadays even without grasping it is forbidden.`,
  '18#ב': `He brings an animal, etc. But not that same animal, lest the redness be because life still remained in it; and there is no comparison to what is written below siman 34, seif 9, that we compare on that same animal, for there the first redness is treifah — therefore there is no stumbling block before us.`,
  '19#_': `Whole ring from the crop — kosher. This is Agur's view: through rolling of the crop it happened thus; and Rashal wrote on this to declare treifah as Rama wrote here: behold any doubt in shechitah is invalid — who will testify it came through rolling the crop after slaughtering the majority of the simanim? Perhaps it was at the beginning or middle of shechitah; and it is reasonable to say that through pressing the knife on the crop a joint jumped from its place — end; and so Maharshal concludes; and even if the ring is not whole, and no difference whether found on the knife or on the ground — in every case it is doubt in shechitah, lest he came to ikkur any amount — end; and he goes according to his reasoning that ikkur at shechitah forbids even any amount; but it has already been clarified there is no distinction except in the whole, as in seif 16; and accordingly if less than majority of the ring is on the knife or ground, plainly kosher, for there is no treifah at all even if caused by pressing the knife; and it appears even if we doubt whether it is majority or not, we follow leniency from safek safeka: perhaps it was not majority — if you say it was majority, perhaps it happened through rolling the crop. Once a case came to me: one slaughtered a goose and after shechitah found on the knife tip one ring — cut, both cut sides on both knife sides; I validated it, for it is clear it did not come through pressing the knife on the crop, for the ring was cut; and we need not fear it was first pushed from its place and then cut thus, for we do not fear pushing at all even for the stringent — rather when we see the ring was not cut and they have some reasoning the knife forgot and pushed without strength to cut; but here we see it was cut — why hold prohibition it was first pushed? Know: if so, when two cuts are found in the trachea and one ring between them, even if not torn from there, we could say that ring was pushed and there were not two adjacent cuts — and this too would be treifah; plainly there is no basis; for it is written siman 21: slaughter in two or three places is kosher — plainly even if adjacent with one ring between; rather certainly we do not hold a presumption except when we see the ring was not cut but came whole — on this we say perhaps it was pushed without cutting. In Sefer Ma'aseh Binyamin I saw at its end in his chiddushim on laws: once a slaughterer slaughtered a goose and when covering the blood found a whole ring on the ashes and I validated it; although in She'erit Yosef, siman 47, he responded to my words and remained in doubt — nevertheless many great ones and slaughterers agreed with me to validate; and so appears the essence, for Agur and Beit Yosef permitted if found on the knife; only Rav Rama was stringent — a novelty; and do not add upon it; and forbid only if found on the knife — end; and Beit Yosef and Agur are fitting to rely on in these matters we mentioned.`,
  '20#_': `His leg to the ground. And the same applies to a wall; and in some books it is written he should not press — and it is a scribal error; it should read he should press.`,
});

// --- baer-heitev (21) ---
patchFile('siman_024/baer-heitev/part-001.txt', 'baer-heitev', {
  '3#א': `Kosher. And Shach wrote: even l'chatchila it is permitted; and Rashal and Bach were lengthy and conclude: both in animal and bird one should slaughter only with a knife that has the measure of two necks of that thing being slaughtered.`,
  '3#ב': `Both. And Shach wrote: what the Mechaber wrote — if the knife has the measure of three necks, kosher — means whether he placed the knife at the beginning on the width of both heads and the knife length extended a full neck beyond both heads and drew to the other side until nothing remained protruding on that side, or he began at the knife edge and drew until a full neck extended beyond the second head — then certainly on both heads he passed two full necks, kosher; but plainly if he placed the knife on both heads' width and drew to the side that protruded beyond both heads a full neck — this is as if the knife has only two necks; and what the Mechaber wrote — if not, concern to forbid both — because since we see one darsahed, we say the second too darsahed, for in one act he passed over both; no difference even if he began at the edge and half the knife passed over the second — both forbidden, not like Bach who distinguished beginning at edge versus placing on both heads in unacceptable matters; and it also appears: if he began at the edge and passed to the other side so the entire knife passed over both — both kosher according to all, simple — not like Bach.`,
  '5#_': `Thus. And Shach wrote: it appears to him the Rav's view is specifically where there is no great loss one should be stringent; but in great loss one may be lenient {Rama: (and Peri Chadash wrote: even in small loss the lenient did not lose; but Beit Yisrael wrote slaughterers now declare treifah even in great loss; and so by experience. Further: one should not slaughter a bird, even a large bird, with a knife used for animals, for easily he will come to darsah. Kenesset HaGedolah wrote to warn slaughterers not to slaughter seated, for sitting leads to darsah. Peri Chadash wrote: b'dieved, whatever he knows he did not darsah is permitted, and so Beit Yisrael. Once someone slaughtered many birds for a wedding resting a finger — Vilna sages permitted b'dieved due to great loss and mitzvah need. One who does not know the laws of shechitah must stand over him from start to finish, even in the last minority, lest he darsah — Kenesset HaGedolah)}. And Taz wrote one should be lenient in all doubts — even if one sees a cut in the spinal column, no need to check majority; all the more if the spinal column is not present — rely to be lenient; stringent only if they already saw true majority of spinal column was slaughtered, not in another matter; and this majority of spinal column — the essence depends on the cord life depends on.`,
  '7#א': `To a siman. And it is called haladah — explanation: language of hiding, for therefore called weasel in this language, for it hides in the earth.`,
  '7#ב': `Invalid. And Shach wrote: all the more if he inserted the knife under both simanim and slaughtered them from below upward, or slaughtered the lower from below upward and the upper properly — haladah; and in all of them it is doubt of neveilah, for they were unresolved and not clarified.`,
  '8#א': `Invalid. Explanation: from doubt.`,
  '8#ב': `In this. And Taz challenged this view from Talmud Yerushalmi that it is not so: in chapter Behemah HaMekasheh (Chullin daf 74) Rav Oshaya asked: he put his hand in the animal's womb and slaughtered a nine-month fetus — why not forbid from haladah, for the knife is not exposed? Rather haladah is only under the cloth tied on its neck. See responsum of Shevut Yaakov, question 45, answer on this challenge; and in Sefer Nekudot HaKesef.`,
  '8#ג': `Haladah. And Shach wrote: but in birds, if he can slaughter without plucking feathers, better; and if impossible, he may pluck feathers so he does not come to haladah; but plucking feathers from a live bird from its wings for writing is forbidden due to tza'ar ba'alei chayim — Maharit in the name of Beit Yosef.`,
  '9#_': `L'chatchila. And Bach forbids even b'dieved; and Taz disagrees. Shach wrote: specifically as here, where where he slaughters is exposed; but in the first law, when the knife is covered by skin where he slaughters — even b'dieved invalid.`,
  '11#_': `Invalid. And Shach wrote: the esophagus is meant — for in the trachea haladah in the first minority is not forbidden, like half a defective trachea, above end of siman 21; and at the beginning he also forbids if he slaughtered majority of one siman and inserted under the remainder — specifically in an animal; but in a bird, once one siman was slaughtered it is fit and haladah no longer invalidates. Maharim Tiktin wrote: this latter part certainly deals when he inserted under skin and slaughtered the first minority from above downward and afterward slaughtered the rest not in haladah — this is what he adds to the first division, where he slaughtered the first minority from below upward — worse.`,
  '12#א': `Shechitah. And Shach wrote: specifically majority of the cavity of the trachea; but majority of the ring does not suffice, for it does not surround the entire trachea except the upper ring.`,
  '12#ב': `L'chatchila. And Shach wrote: but in hagramah he validates, since hagramah is not the place of shechitah, it is as if he drew with hand or foot.`,
  '13#_': `Invalid. And Shach wrote: what is written here — if he darsahed or inserted in the first third, etc. — refers to what he wrote before: hagramah on a third and slaughter two thirds, or slaughter a third, hagramah a third, slaughter a third — kosher; on this he says: do not think that since with hagramah on one third it is kosher, likewise if he darsahed or inserted the first or middle third it would be kosher; for since hagramah is not in the place of shechitah we do not count it — and if so as if he darsahed or inserted in the first minority; he teaches it is not so; therefore he said: if he darsahed or inserted in the first third — meaning not slaughter a third, hagramah a third, slaughter a third, but darsahed or inserted a third, hagramah a third, slaughter a third; or in the middle third — meaning not hagramah a third and slaughter two thirds, but hagramah a third, darsahed or inserted a third, slaughter a third — his shechitah is invalid; for we require majority in shechitah specifically; and now the Mechaber deals properly with the trachea, therefore certainly invalid — and this is clear to me — end.`,
  '15#א': `And from the flesh. And Shach wrote: but if the flesh tore with the simanim, even if all uprooted — he holds kosher. Maharim Tiktin wrote: according to the Mechaber, even for the view of one who invalidates what he mentioned above in seifim 10 and 12 — ikkur is not like darsah and haladah; what was slaughtered properly and shechitah fitness completed — the majority — if he uproots the remaining minority after shechitah, kosher, because it is not the manner of shechitah; and according to the gloss, who was stringent above in hagramah though not the manner of shechitah, he was stringent here too for ikkur. However, if it slipped before shechitah, we establish according to law; and this is what Rama wrote "but while alive," etc.; and from Rama's words it appears even if the majority dangled while alive, milk and eggs are kosher; but most poskim hold if the majority dangled it is actual treifah even while alive — Shach. Also what Rama wrote practical difference for milk — Peri Chadash, siman 14, s.k. 11, disagrees and forbids milk and eggs.`,
  '15#ב': `One of them. And Shach wrote: even in a bird, whose fitness is one siman — nevertheless we require both fit for shechitah.`,
  '16#_': `The whole. And Taz wrote: even at the time of shechitah ikkur forbids only in the whole, not any amount; specifically when torn in one place that minority remained in strength, unlike when torn in many places — Maharim Tiktin in the name of Rashba, and the author of Hagahot shechitah did not write well; and Shach in Sefer Nekudot HaKesef disagrees with Taz; and so Peri Chadash wrote.`,
  '17#א': `Invalid. Explanation: from doubt; and we do not say if it had been dangling beforehand he would have seen or felt it — who can distinguish this? — therefore invalid from doubt; and it deals with a bird.`,
  '17#ב': `Shechitah. And Taz wrote: although I wrote above one cannot distinguish at shechitah — here it must deal where after shechitah in the place of slaughter a change is seen from what it was at shechitah — the uprooted place turned and came there; with this he is believed to say it was not so at shechitah; unlike above where nothing of uprooting is seen at slaughter place, only above at jaw connection still covered in skin — certainly he cannot distinguish.`,
  '18#א': `Invalid. The reason: then it is possible it was already dangling and he slaughtered afterward, since he grasped the simanim; and Maharshal wrote: nowadays even without grasping forbidden; and if both are found slaughtered and one dangling and he grasped the simanim — we are lenient in a bird from safek safeka whether the dangling was slaughtered before slipping, or if slaughtered first, whether it slipped before the second siman — see Erech Lechem.`,
  '18#ב': `The first. And Bach wrote: but not that same animal, lest redness be because life remained; and unlike what is written below siman 34, seif 9, comparing on that animal, for there first redness is treifah — therefore no stumbling block — end.`,
  '19#_': `One should not deviate. And so Rashal; and in responsum of Nishmat Shabbat, siman 69; and see responsum of Chavot Bair, questions 25–28. However, if found on the ground — doubt in She'erit Yosef, siman 47, and in Mishnah Berurah, siman 100, he validated if found on the ground; and Bach was stringent even if the ring was cut on one side — see there; Taz was lengthy; and Peri Chadash brought the poskim and concludes we validate in every case like the Mechaber; and Pri Megadim also brought the latter authorities and concludes: when cut on one side and the other side of the ring rests on the knife tip with both points of the ring on both knife sides — kosher, for we see clearly they were not uprooted before shechitah — how could the ring be cut on one side unless the knife uprooted the other side because it was not sharp enough to slaughter the second side, therefore the ring was uprooted after majority of trachea slaughter; and even when half the ring falls on the ground or was on the knife, there is no pain concern at all and kosher; but if found whole on knife or ground — all forbid; also when the cut of the ring hangs on the crop — also kosher — see there in She'erit Yosef, siman 46; and Shach wrote: even if found on ground, treifah — not like Ma'aseh Binyamin; and Taz wrote: once a goose was slaughtered and after shechitah found on the knife tip one ring — cut on both sides — I validated, for no basis to hold presumption except when we see the ring was not cut but came whole — on this we say perhaps pushed without slaughter; see Shevut Yaakov, question 46, who agreed with Taz — not Shach; and see responsum of Maharam Lublin, siman 24.`,
});

// --- beer-hagolah (20) ---
patchFile('siman_024/beer-hagolah/part-001.txt', 'beer-hagolah', {
  '1#_': `Mishnah, Chullin daf 30, according to Rashi's explanation there and Rambam's explanation, chapter 3 of Hilchot Shechitah, law 11.`,
  '2#_': `There in the mishnah.`,
  '3#_': `Conclusion of the Gemara there, daf 31.`,
  '4#_': `There in the mishnah.`,
  '5#_': `There in the mishnah and there in the Gemara.`,
  '6#_': `Baraita there, daf 40.`,
  '7#_': `Kol Bo in the name of Rif; and so Hagahot Maimoniyot, chapter 3 of Hilchot Shechitah, in the name of Semak.`,
  '8#_': `There.`,
  '9#_': `In the mishnah there, daf 32.`,
  '10#_': `There in the Gemara, daf 34, from the statement of Rav Yehudah in the name of Rav.`,
  '11#_': `Unresolved matters that were not clarified there — and stringently.`,
  '12#_': `According to Ra'osh's explanation.`,
  '13#_': `According to BeHaG's explanation.`,
  '14#_': `Tur and Ran there in the name of the rabbis; and so Semag [in BeHaG], Ra'osh, Rashba; and so from Rashi, Semag, and Rabbeinu Yerucham, and BeHaG.`,
  '15#_': `Rambam, chapter 3 of Hilchot Shechitah, law 10.`,
  '16#_': `Beit Yosef.`,
  '17#_': `Tur in the name of Semag and Hagahot Maimoniyot.`,
  '18#_': `There in the name of R' Eliezer of Metz (in Sefer Yereim, 336).`,
  '19#_': `Hagahot Maimoniyot, chapter 3 of Hilchot Shechitah.`,
  '20#_': `So from Rambam's words, chapter 3; and so Ra'osh, chapter HaShochet, in his name, and he relied on the tosefta.`,
});

// --- beur-hagra (38) ---
patchFile('siman_024/beur-hagra/part-001.txt', 'beur-hagra', {
  '1#_': `Darsah — how so, etc. The language of Rambam; and so Rif; and as in the mishnah there: whoever did not do holacha and hava'ah — likewise darsah.`,
  '2#_': `And some, etc. — for they hold it was said only in a bird whose neck is thin.`,
  '3#_': `There is concern, etc. — Ran. To exclude Ra'osh's view, who forbade only the second; but Ran forbids both, for both were slaughtered as one — if they were darsahed, both were darsahed.`,
  '5#א': `(Likut) If he was, etc. — for what is written "not like," etc. — explained in Tur HaDeshen that blood should not be absorbed in limbs; and for blood it is needed in kodashim; and even in non-sacred it is forbidden, as in chapter Kol HaBasar (113a) — see there (end).`,
  '5#ב': `And the custom, etc. — as Rashi explained there, 27a, s.v. delo leshavya, etc.; and the first reasoning holds like Mordechai on what Rashi wrote "no more" — meaning no more is needed; and Rashba explained because of blood absorption in limbs it is forbidden. (Likut) And the custom, etc. — see Mordechai and Hagahot Alfasi, chapter 2, s.v. vekara, etc.; however in the tosefta, etc. — but the tosefta is not understood as their explanation; but the essence is like the first reasoning, and the tosefta's explanation is regarding darsah, as in the mishnah "he was slaughtering and removed the head," etc. — kosher; and Or Zarua, siman 67, and provided he does not grasp, etc.; and in such a case the tosefta deals when the knife has a full neck and he did not draw the entire knife (end).`,
  '6#א': `And even, etc. — as in the tosefta on shehiyah; and we compare there to perforation — and the same for all disqualifications of shechitah.`,
  '6#ב': `And the custom, etc. — as above: in the last minority we rule like Rashi; and in the first minority of the trachea too, from concern we are not expert in examination and we fear the esophagus, as in the tosefta on shehiyah.`,
  '8#_': `(Likut) Under the skin. Like the house of Rav we take and declare invalid there according to him — Tur HaDeshen (end).`,
  '9#_': `One must, etc. — as written above, chapter 2, because he inserts; and by Torah law he followed the stringent view; and in Hagahot Alfasi there and in Tosafot there, s.v. mipnei, etc.; and Rashal wrote: although Tosafot rejected Rashi's words in Zevachim, nevertheless poskim upheld his words, for even though according to their view it cannot be explained, nevertheless according to truth Rava's words can be explained thus; and he wrote: although Rava holds it is not inserting, we do not rule like Rava, who holds drawing and bringing in melikah is invalid, and we rule like those who hold kosher, as Rambam wrote; and Rashal wrote his reason because we say there, 20a: R' Avin wanted to say, etc.; R' Yirmiyah told him, etc.; and we say there: sons of R' Chiya, etc. — they alone hold thus; and he wrote: although at first glance halakhah follows Rava as the later authority, truth is there is no Rava, only Rabbah — and so Rashi there, 20a, s.v. hanicha, etc.`,
  '10#א': `If after, etc. — as in the tosefta on shehiyah and Rav Pappa's question there, 32b, as in siman 11 — see there.`,
  '10#ב': `And the custom, etc. — as above: in the last minority we rule like Rashi; in the first minority we fear the esophagus, for we cannot examine, as in the tosefta on shehiyah.`,
  '11#_': `And likewise if he did a minority, etc. — meaning under the skin — Taz.`,
  '12#א': `How so — this one, etc. — or, etc. — as Kesef Mishneh there: they disagree whether he slaughtered and did hagramah or hagramah and slaughtered — as below.`,
  '12#ב': `But if he slaughtered the majority, etc. — as written (18a): Rav and Shmuel both said, etc.; and Tosafot there, s.v. aval; and it appears to explain: even Ribbi, etc.; and there 19a for the latter wording — in such a case kosher according to those who hold kosher.`,
  '12#ג': `Or in darsah — like all disqualifications according to Rambam, as above, as in the tosefta on shehiyah and the Gemara on hagramah, as here.`,
  '12#ד': `And there is one who invalidates, etc. — Ribbi's view, who explains like Rashi: Rav Pappa's question there, 32b, and Rav Huna son of R' Nachman's question there, 32a — deal with the last minority; and from there we learn for darsah and hagramah that they differ, for not in the place of shechitah; and the same for ikkur not from shechitah — as below.`,
  '12#ה': `And the custom, etc. — as above we rule like Rashi.`,
  '13#א': `Hagramah, etc. — in BeHaG; and as above. (Likut) Hagramah, etc. — as the latter wording: both Rav Yehudah and Rav Huna agree majority is in shechitah; and when life departs, etc.; and although at first glance there, 20a, the sugya is like the first wording — one may say for the rabbis he spoke. Slaughtered, etc. — hagramah, etc. — like Rav Yehudah, for R' Nachman holds thus, etc.; and in Tur HaDeshen he ruled everything stringently only like the first wording for Ribbi son of R' Yehudah (end). (Likut) Hagramah, etc. — slaughtered, etc.; and in Tur HaDeshen he disagrees entirely with what is written, 20a, and like Rav Huna, etc. — apparently the sugya is like this wording; and the same in the other that is invalid — see there (end).`,
  '13#ב': `And if he darsahed or inserted, etc. — like shehiyah.`,
  '14#א': `All these, etc. — as in shehiyah in the tosefta; and we compare there to perforation — and the same for all disqualifications of shechitah; and in the Gemara there, 43, and 44, on hagramah: that ox of the sons of, etc.`,
  '14#ב': `Whether downward. — for the Gemara there gave the reason because its perforation is in any amount — and the same downward, as "the thin ones were perforated," and as Rashi explained, beginning of chapter 3, s.v. elu treifot: any perforation in any amount.`,
  '14#ג': `And likewise on the trachea, etc. — as written, 45a; and Rashi there, s.v. lemata, etc.`,
  '14#ד': `And the custom, etc. — as above in the gloss.`,
  '15#א': `(Likut) Ikkur, etc. — from what is written, chapter 3 (44a): and there is ikkur of simanim; and further, according to Rashi, how did they say there, 20: there is no ikkur of simanim in a bird? — yet the mishnah teaches: these treifot in a bird — perforated esophagus, etc.; and they said there: that disputes Shmuel, who holds even in shechitah there is no ikkur for a bird (end).`,
  '15#ב': `From the jaw and from the flesh. — as written there, 44a: the challenge — if uprooted, etc.`,
  '15#ג': `And one of them slipped out. — there, 10a; and there, 28a; and BeHaG's explanation in Tosafot there, 9a, s.v. kulhu — see there. (Likut) And one of them slipped out. — there, 28a, because of the crop, etc. (end).`,
  '15#ד': `But if he slaughtered one, etc. — there, 10a; and there, 28a.`,
  '15#ה': `One slipped out, etc. — there.`,
  '15#ו': `And we, etc. — as above.`,
  '15#ז': `And specifically, etc. — Tosafot there, 9a, s.v. kulhei; and in Beit HaNidash he explained, etc.; and they asked: it is obvious, etc.; and one may say according to BeHaG, etc.`,
  '16#_': `And this applies when the majority was uprooted, etc. — as written: simanim that dangled in their majority specifically; and we establish it was torn apart.`,
  '17#א': `If he slaughtered, etc. — there, 10a; and there, 25a.`,
  '17#ב': `And even if he threw, etc. — as written there: even though he was occupied with that species, etc., and we do not attribute; and there compared to doubt in shechitah; and even for R' Chiya, who distinguishes there as written, siman 18: knife deteriorated — animal did not deteriorate, unlike here where the bird itself deteriorated; and what Tosafot explained there, s.v. sakkin; and one may say: what difference to me, etc. — does not apply here; and on Maharik there.`,
  '17#ג': `However, etc. — as written there: until he says clearly to me it was not on me, etc.; and on Tosafot, beginning of Gittin, 2b, s.v. alav: believed regarding prohibitions — Kuntres explained, etc. — see there.`,
  '18#א': `Found, etc. — according to Ra'osh: R' Yochanan is stringent against Rav; and Rav Nachman explains their words; and halakhah follows R' Yochanan and Rav Nachman. (Likut) Found, etc. — as the text "Rav Nachman said"; and to explain R' Yochanan's words. Ra'osh; and in Tur HaDeshen he wrote: even for the text "Rav Nachman said" one may say thus; and further, since it is a Torah prohibition and halakhah was not interrupted — if like Rav Nachman or like R' Yochanan, one must act stringently like both; but Rambam and Razah ruled only like R' Yochanan alone, and everything follows grasping or not (end).`,
  '18#ב': `And now, etc. — Hagahot Maimoniyot.`,
  '19#א': `If he slaughtered, etc. — through rolling of the crop when he slaughtered in two or three places it happened thus.`,
  '19#ב': `And some declare treifah, etc. — as written (10a, 28a): any doubt in shechitah is invalid.`,
});

// --- kereti (34) ---
patchFile('siman_024/kereti/part-001.txt', 'kereti', {
  '2#א': `And the spinal column — certainly one does not slaughter the spinal column; only if he measures the width of the simanim — trachea and esophagus are minorities — he measures only the width of the spinal column, for the simanim slip sometimes on this side of the spinal column, sometimes on the other — therefore he estimates the full width.`,
  '2#ב': `In an animal, since its neck is hard and the knife small, it comes under darsah.`,
  '3#א': `Slaughtered two heads, etc. — likewise l'chatchila permitted to do so; and that which he stated "slaughtered" is because of the latter part "there is concern for both" — even if already slaughtered, we forbid.`,
  '3#ב': `Kosher — even if he placed the knife on both as one, or drew, or brought.`,
  '3#ג': `And there is concern — see Peleti, where I aligned with Ra'osh's intent and the authors, especially Ramban's words; and for us, who forbid darsah in the last minority — plainly one should be stringent in every case, as Peleti wrote at length.`,
  '5#א': `Only majority — and Taz's view is specifically the cord he grazed with.`,
  '5#ב': `And one should not deviate — many authors are lenient; and already Maharal of Prague ruled to be lenient; and this appears specifically if he slaughtered unintentionally; but intentionally, l'chatchila, to slaughter with the spinal column one should be stringent, for thus the tosefta teaches, chapter 2 of Chullin: he was slaughtering and cut — in Beit HaMikdash, if he intended — invalid; if not — kosher; therefore all proofs to validate are without intent; but with intent there is no proof against the tosefta — one should be stringent.`,
  '6#_': `Not to rest a finger — in great loss one may permit b'dieved if he says clearly he did not darsah on the last parts.`,
  '7#א': `Haladah — language of hiding; and see Peleti, where I analyzed Taz's wording that wrote "like a weasel that returns to the foundations of houses" — and this is the meaning.`,
  '7#ב': `Whether he slaughtered the upper — and the same; and all the more if he inserted the knife under both simanim and slaughtered both from below upward, or one from below upward and one from above downward.`,
  '8#א': `Tied on its neck — the same if wrapped on its neck — only it must be in a manner the wrap tightens the cloth on the neck; but if the cloth is wrapped so it can fall off the neck — then it is mere covering — so all poskim imply.`,
  '8#ב': `Invalid — meaning from doubt, for this was unresolved and the Mechaber was not precise — though there is great practical difference between doubt and certainty.`,
  '8#ג': `And there is one who forbids — Rambam's view; and Taz sought to reject this law; and see Peleti what I wrote — on the contrary, from where it comes there is proof for Rambam.`,
  '8#ד': `In sheep — and the same in birds that have feathers until the knife is covered — pluck them somewhat before shechitah so blood does not come out.`,
  '9#_': `And one should heed, etc. — when he slaughters in the middle the knife is exposed; but if torn in skin, etc. — even b'dieved invalid — Shach.`,
  '11#א': `Under the first minority — this is haladah: he inserted under the minority and slaughtered in haladah from below upward that minority; but if he inserted under skin and slaughtered a minority of simanim and afterward tore skin and slaughtered the rest properly — this is not dealt with here; and it deals when skin was torn from the start, as Bach wrote; and see Peleti — insertion under skin and slaughtering only a minority in haladah — there is room to validate — see there.`,
  '11#ב': `In an animal — but in a bird, once one siman was slaughtered it is fit — what can haladah afterward invalidate?`,
  '11#ג': `And likewise if he slaughtered the first minority in the esophagus — certainly invalid, for it is only a disqualifying perforation; but in the trachea — Perishah and Shach would permit by law; and Maharshal and Bach forbid; and Shach challenged him; and see Peleti — do not reject Maharshal's words, he has great pillars; otherwise for us, who declare treifah everywhere, no difference.`,
  '12#א': `Majority of the cavity of the trachea — but not majority of the ring, for except the large ring, majority of a ring is not majority of the trachea cavity; and see above siman 20, Peleti at length.`,
  '12#ב': `Who invalidates in darsah — for hagramah is not the place of shechitah, unlike this who slaughters in the place of shechitah — the disqualifying matter.`,
  '13#א': `Invalid — for the majority is in hagramah.`,
  '13#ב': `And if he darsahed, etc. — all wondered why certainly treifah and neveilah — behold Rambam wrote earlier: if he slaughtered a minority of simanim in haladah and completed not in haladah — doubt of neveilah; and Kesef Mishneh explained this too means doubt of neveilah — forced; we do not find the Gemara doubts darsah; and Shach wrote he speaks collectively — when he inserted a third, hagramah a third, slaughtered a third, in any case there are two majorities in disqualification; what difference haladah and hagramah; and see Peleti — truly complete haladah or darsah in the first minority is certainly invalid; and above regarding haladah called doubt because it was not clear haladah — the doubt was whether it is haladah at all when inserted under minority of siman — on this we judge; and this is clear; and so Peri Chadash's view.`,
  '14#א': `And likewise on the trachea, etc. — its perforation in any amount; and one law applies with the esophagus.`,
  '14#ב': `Invalid — Shach brought Ribbi's view: even for one who doubts haladah in first minority of esophagus, all agree here it is not the place of shechitah and the manner of shechitah does not apply; and see Peleti — no need, for these authorities also forbid haladah in first minority.`,
  '15#א': `Such as uprooted — and the same: a flawed knife is also called ikkur.`,
  '15#ב': `Before completing shechitah — even in a bird, for only one siman is not required — nevertheless both must be fit for shechitah.`,
  '15#ג': `Whether in the last minority — according to law the last minority is kosher, only our custom forbids; and Bach's view: if flawed in the last minority, forbidden by law; and see Peleti — I brought proof from Tosafot that even flaw is permitted by law.`,
  '15#ד': `Only shechitah does not help — but simanim that dangled in majority are treifah according to all; and so Shach wrote — correct.`,
  '15#ה': `Its milk is kosher — see Peleti where I discussed this and raised the reason: according to BeHaG, ikkur can return to health.`,
  '17#א': `Invalid — it is a Torah doubt stringently; and impossible to distinguish.`,
  '17#ב': `However, the slaughterer is believed — meaning he said he felt clearly and has signs for this — Taz.`,
  '18#_': `Invalid — since he grasped in his hand, it can slip and be slaughtered while dangling — invalid by law of the sugya.`,
  '19#א': `Kosher — although it is doubt of prohibition, we hold it is not common for a crop ring to slip while alive without the blow being evident and blood clotted; and we always rely on the common case; and see below siman 50.`,
  '19#ב': `And some declare treifah — for Torah doubt is stringent; and it is a whole ring or majority; but for a partial amount we have no concern — crop severance in majority; and if doubt whether majority — Taz validates also from safek safeka; and see latter responsa who were lenient in several matters; and since I do not intend to be lenient, I did not bring their words — whoever wishes to rely may see in books.`,
});

// --- peleti (11) ---
patchFile('siman_024/peleti/part-001.txt', 'peleti', {
  '3#_': `Both, etc. — in my humble opinion I could not descend to the end of Beit Yosef and the latter authorities' view; therefore I will copy the early authorities briefly. In Chullin daf 31 they said: we require beyond the neck a full neck — Tosafot wrote: at first glance it appears one must draw that entire full neck beyond the neck, therefore this measure is needed; however it appears one need not; this measure was only so he slaughters with ease; sometimes the knife is sharp and he slaughters without drawing the full neck — end; and so Ra'osh. Now see what Ra'osh wrote: there are two animals slaughtered as one, and the knife has only two necks' measure. And distinguish first from inner. We explain with a parable: one animal, neck four fingers abcd placed; beside it animal also four fingers hezach; knife eight fingers abcdefgh. If so, when he begins slaughter through drawing, knife letter aleph comes to animal one's daleth; when he draws, slaughter on both — behold aleph of knife on animal two's daleth. Ra'osh's view: validate first, invalidate second; and reverse — then aleph of knife comes to animal two's daleth; then second kosher, first invalid. Beit Yosef learned: always the full eight-finger knife must pass over each animal's entire neck; therefore in the first manner of drawing, he draws the knife over animal one's entire neck from cheth until aleph passed; but on animal two at completion only aleph of knife on its daleth — only four fingers passed on the neck — from this Beit Yosef derived: if he wanted to pass the entire knife beyond until cheth of knife on animal two's hei — all eight passed — kosher; and reverse in bringing — only four fingers passed on first animal, rest remain on second — treifah; but if he drew and brought until cheth of knife on animal one's aleph and entire knife beyond animal also — kosher. And if so, everything depends on Tosafot's reasoning that we require the entire two necks, i.e. eight fingers, on each animal; and Tosafot rejected this, especially Ra'osh — for with a sharp knife he cuts easily immediately without passing the entire knife; only Tosafot and Ra'osh: with a long knife he does not darsah; but a short knife only according to the animal darsahes — it appears this knife must be free, not busy with another slaughter — then it is a long, spacious knife; but when four fingers remain on the knife for another slaughter, there is no spaciousness — it is as slaughtering with a four-finger knife holding also four fingers — therefore here, slaughtering two animals as one with drawing or bringing alone, certainly the essence of slaughter cannot be as one, for one animal's majority was slaughtered before the second; only called as one because completion is as one — when bringing knife from one animal to the other, the first's majority was finished before reaching the second; but when coming to slaughter the second, the first's majority completes — called as one; and so Taz's view — see there; therefore one cannot say when beginning with drawing that both finish truly equally — only first head of knife cheth begins at first neck's start aleph and draws — at first neck's end daleth, hei of knife arrives and four letters remain outside animal — then he slaughters with spacious eight-finger knife — kosher; but at second animal's end, cheth of knife on its cheth — four fingers on first animal to complete majority onward, and four on second — no free knife, for on second cheth to hei, and aleph–daleth of knife on first to complete — no free knife, no spaciousness — therefore darsahed and second treifah; and reverse in bringing from second to first — half knife on first aleph–daleth and on first aleph–daleth, but hei–cheth remain on second to complete — no spaciousness — invalid; and if so, always one treifah one kosher — no difference if he passes knife afterward on all; for at slaughter time knife must be spacious and free — if not, treifah; and what he does afterward — what difference; therefore I did not descend to Beit Yosef's end. Ramban challenged: when one is darsahed, the second too; and in this too I did not succeed — for the first slaughtered with drawing has spacious eight-finger knife, neck only four — not darsah; afterward on second there is no spaciousness and he darsahed; if so, then on first too he darsahed after majority slaughtered — what is Ramban's view that darsah in last minority is treifah? — understand; and perhaps when he begins he sees on second animal there will be no spaciousness and prepares to slaughter forcefully — darsah — then even first was darsahed — understand; in any case for us who forbid darsah in last minority, Ramban's words are correct without doubt — examine, for the weakness of intellect in my humble opinion.`,
  '5#_': `Majority of spinal column — Taz brought Rashba on "we do not make it a block" — meaning do not break spinal column before shechitah, then blood absorbs in limbs, etc. — end; and Taz challenged in chapter 2: if so by Torah one may not break spinal column — why does salting help? — and Rashba himself ruled salting helps — see there. Shach answered in Nekudot HaKesef: the verse teaches us that even in kodashim where blood is needed, therefore do not break spinal column, etc.; and wrote: so it is correct — do not say anything; for Rashba daf 23 brought one derivation for kodashim and one for non-sacred from "and you shall slaughter from your herd" — if so the challenge is on the verse for non-sacred, not Shach's words; therefore the essence is the mitzvah of shechitah is to break spinal column and remove head, for thus the soul departs, as the mishnah in Ohalot teaches — through this it leaves the category of alive; and if so, permitted to eat raw, for it is not blood — the verse teaches not commanded thus; and automatically we know raw is forbidden as blood (that was not) explained — only through salting permitted, blood absorbed separates and is expelled — simple.`,
  '7#_': `Haladah — Taz wrote s.k. 3: language of hiding, therefore called haladah because it hides in earth — so in the Gemara. But the Gemara implies the opposite — on melikah with a knife they said slaughter invalid: one says darsah, one says inserting; the Gemara asked: one who says darsah — why not say inserting? And answered: how is haladah? Like a weasel returning to house foundations — it hides; and this reveals; and because he inserts there, Tosafot explained he slaughters simanim from below upward — see there; behold this is not like a weasel; and we rule haladah with a narrow knife slaughtering from below upward — if so, we do not require similarity to a weasel, only mere hiding; and in Maharshal this extra wording in Taz is superfluous.`,
  '8#א': `Invalid — from doubt, for this was unresolved.`,
  '8#ב': `And there is one who forbids in this too — Taz challenged: the Gemara asked — Rav Oshaya put his hand in the animal's womb and slaughtered — why not forbid haladah, like a cloth spread on its neck? — no challenge: spread on it is unresolved; if so that question deals whether if not haladah at all, does slaughter in the womb help; and so appears in Perishah; therefore possible, as I wrote siman 14, Rambam was precise from the egg to escape Tosafot's challenge — could he insert his hand in its mother's womb and slaughter — like slaughtering at night — Rambam does not hold b'dieved kosher and called it prepared; therefore he explained it is haladah, as Atzei Erez and Taz wrote — their words are compelling; and see what I wrote siman 14 — the words fit Rambam's approach — understand.`,
  '11#א': `Under the first minority and slaughtered from below upward — the matters imply haladah was inserting under the first minority and slaughtering it in haladah — not simply inserting under skin and slaughtering minority of siman and tearing skin afterward — haladah in first minority; and Shach in s.k. 11 wanted to explain thus in Shulchan Aruch — but the wording "inserted the knife under the first minority" does not imply thus, as Bach understood; and I do not know: since under skin we do not know, and haladah in minority of simanim was unresolved — it would be safek safeka: perhaps no haladah under skin; and if you say haladah — perhaps minority of simanim is not treifah; and likewise reverse; therefore Shulchan Aruch omitted skin — understand.`,
  '11#ב': `First minority in haladah — Shach and Perishah mean the esophagus — any amount forbids; but in the trachea — Perishah and Shach would permit by law; Maharshal and Bach forbid; Shach challenged; and see Peleti — do not reject Maharshal; he has great pillars; otherwise for us who declare treifah everywhere, no difference. Maharshal's words appear correct in shehiyah — though Ashkenazi shechitah Beit Yosef brought implies even in shehiyah one may say they were stringent; see there — he admits clearly this is only for validation; but by law he did not decide to validate; and so Ra'osh's words in Rashba's responsum 267 explicitly: for Rashi, even in trachea first minority not forbidden — examine and find like my words. Truth: the challenge from the baraita "half trachea slaughtered and paused — kosher" — at first glance a refutation; but to resolve: those authorities hold it depends on Ribbi and the rabbis — Ribbi suffices with majority in fitness, rabbis require all in fitness at start and end; see there daf 30, Rashi and Tosafot — you will see; and one may say that baraita on shehiyah in first minority is Ribbi; but as we rule stringently like the rabbis, as Rashi wrote, even shehiyah in trachea first minority invalidates. With this, resolve Rabbenu Tam's challenge from tosefta and baraitot contradicting each other — say one is rabbis, one Ribbi — see Tosafot daf 30b, s.v. hachalid; at least leave shehiyah in first minority in place; but darsah, haladah in trachea first minority — many authorities invalidated, as Beit Yosef in Ashkenazi shechitah, with reason: in shehiyah he stands in slaughter and does not slaughter in disqualification; unlike darsah and inserting, where he slaughters in disqualification and acts to disqualify. What more than BeHaG (and Rashba in responsum aimed at him), who wrote haladah in first minority of simanim is forbidden d'oraisa; and if he inserted the knife between simanim and regretted before slaughter — remove gently and slaughter elsewhere and check if he hit trachea or esophagus; and the challenge on hitting trachea — what difference, haladah in trachea minority? — learn he forbids as Ashkenazi shechitah wrote; and more authorities hold thus; and if so, heaven forbid to reject Maharshal's four words where he has a trusted pillar to be stringent.`,
  '13#_': `And if he darsahed or inserted, etc. — Ribash and more rabbis cried out: behold Rambam wrote: and if he slaughtered a minority of simanim in haladah and completed not in haladah — doubt of neveilah, unresolved; and here he ruled certainly invalid. And see Shach who wants to say Rambam deals with the same third where he inserted, etc.; the forcedness is clear; as Peri Chadash wrote; and the shorter path in Rambam's words: since Rambam explains the unresolved matter of shehiyah in minority of simanim, as Mechaber above siman 23, seif 4 — meaning pause time of slaughtering minority of simanim near majority; see what I wrote there; in any case he does not explain simply pause from start when he slaughtered minority of simanim — he holds plainly treifah, for any perforation in esophagus forbids, and shehiyah is perforation, as Tosafot and tosefta on shehiyah in first minority of esophagus forbid. Accordingly, also in the unresolved haladah in minority of simanim — Rambam must explain like Rabbenu Tam: he slaughtered four measures of trachea, majority properly, minority remaining he inserted under and cut from below upward; if so, the doubt is whether this is called haladah, since otherwise majority was slaughtered. This is Rambam's intent; and "if he slaughtered a minority of simanim in haladah" — haladah was inserting under the minority and the haladah itself was inserting under the minority of siman not yet slaughtered; though wording is somewhat forced, he resolves himself and it is doubt; but afterward Rambam in the body of the law makes haladah that is haladah without doubt — only he did not slaughter in haladah only a minority of simanim — certainly treifah, as above from tosefta; on this Shulchan Aruch has no doubt, only doubt whether called haladah; and so the authorities teach. Peri Chadash's words, except he was lengthy unnecessarily and wrote Tur illuminated path, etc. — he did not speak correctly here: for according to the unresolved shehiyah in minority of simanim, Rambam cannot explain on first minority, for in his view certainly treifah without doubt; and therefore the explanation is as above — when fitness measure near majority, etc.; and Tur in siman 23 wrote explicitly Rambam explains that unresolved matter on first minority — if so, he does not hold thus in Rambam; and see Beit Yosef; but truth guides that this is better than all explanations.`,
  '14#_': `Invalid — meaning certainly; and Shach wrote s.k. 20: although haladah in first minority of esophagus is doubt of neveilah, Ribbi distinguishes: since in the manner of shechitah one may say it is not a perforation; but hagramah, not in the place of shechitah, is a perforation. And Ribbi's words were not needed — Ra'osh and Rashba truly do not explain on haladah in first minority as Ribbi — Ra'osh on haladah in last minority, Rashba like Rabbenu Tam; if so, one may say in complete haladah in first minority they agree it is invalid — and Ribbi's distinction is not needed.`,
  '15#א': `Whether in the last minority — ikkur in last minority is permitted by law; and Bach wrote: only if simanim were uprooted; but a flawed knife, also ikkur — even in last minority forbidden by law. A novel prohibition without proof; we find no hint in poskim; but Tosafot, Niddah, 2b, flawed knife — Tosafot wrote several doubts: perhaps in spinal bone or last minority it was flawed — learn he holds animal kosher in last minority, not like Bach — understand.`,
  '15#ב': `Regarding its milk — Taz challenged: in Chullin daf 69 the Gemara says: one may say therefore ordinary milk, though from its mother, is permitted, for there is remedy through shechitah; and eiver min hachai — why need remedy through shechitah? — here regarding ikkur what of it — it is not treifah, there is no remedy — nevertheless milk forbidden from eiver min hachai. Taz answered: what they said "there is remedy" means the eiver min hachai prohibition is lighter, therefore even in ikkur milk is not forbidden. I wonder: Rashba in his chiddushim, chapter Behemah HaMekasheh, challenged: what is the question on an animal with eiver min hachai if its milk is permitted — obvious it is forbidden like treifah milk; and Rashba answered: eiver min hachai has no name of treifah, only lack of shechitah fitness — slaughtered is like eiver min hachai; therefore the question: does it enter the leniency of eiver min hachai? — see there; if so, milk is also forbidden from eiver min hachai — why permit here? — at first glance difficult. What appears to me: certainly Tosafot, Ra'osh, Rashba all spoke whether it is treifah or not — not practical difference; forced to say all thought about milk. Therefore practical difference: whether uprooted or slipped simanim can return healthy through medicines — according to Rashi impossible, treifah cannot return to fitness; if we see it healed briefly, it returns. Unlike BeHaG: no treifah, only while uprooted shechitah does not help, not connected, or Ramban's reason — impossible to slaughter properly; but if they return healthy and heal well, in every case kosher — automatically milk permitted, for more permission than shechitah for eiver min hachai — simple and true; though I did not find authors thus — nevertheless all is correct and true.`,
});

// --- pitchei-teshuva (7) ---
patchFile('siman_024/pitchei-teshuva/part-001.txt', 'pitchei-teshuva', {
  '1#_': `<b>Majority of the spinal column.</b> See Ba'er Heitev, s.k. 3; and see responsum of Beit Yaakov, end of siman 162, who also ruled not like Rama — see there.`,
  '2#_': `<b>To detach the wool.</b> See Ba'er Heitev, s.k. 8; and what he wrote: forbidden to pluck a feather, etc., due to tza'ar ba'alei chayim — Rama's words in Even HaEzer, end of siman 5, in the name of Maharai were omitted: everything needed for healing or other uses has no tza'ar ba'alei chayim; nevertheless people refrain, for it is cruelty — see there.`,
  '3#_': `<b>The tangled wool.</b> See in the Gemara, Bekhorot, daf 24b, Tosafot there, s.v. hashochet; and below siman 308, seif 3 — understand.`,
  '4#_': `<b>And we practice to declare treifah.</b> See Shach, s.k. 23: we practice to declare treifah any ikkur, even any amount, etc., since a disqualification occurred in shechitah we practice to declare everything treifah from concern lest the esophagus was perforated — end; and see responsum of Givat Shaul, siman 28, who wrote: accordingly, where he grasped the trachea in his hand and knows certainly he did not touch the esophagus — his shechitah is kosher; but Shach's words are wondrous — see there — he ruled even if he grasped the trachea it is invalid; see Peri Megadim.`,
  '5#_': `<b>And there is a practical difference regarding its milk.</b> See Atzei Erez, s.k. 10; and see responsum of Chasam Sofer, part 2, siman 29, what he wrote on this.`,
  '6#_': `<b>And one should not deviate.</b> See Ba'er Heitev; and see responsum of Shevut Yaakov, part 2, siman 55: he practiced if found on the ground to validate in great loss; and likewise if the ring was cut in the middle and hangs on the trachea, or rests or hangs in the middle on the knife or ground — do not be stringent; and he further wrote he received from an expert slaughterer: if you wish to avoid this doubt of a crop ring common in geese, slaughter pen-slanted obliquely — then tested and proven no ring will be found in their slaughter — end.`,
  '7#_': `<b>Or raise them.</b> See responsum of Shevut Yaakov, part 2, siman 56: asked regarding a slaughterer who slaughtered and pressed his finger on the trachea until it was crushed and he heard the sound of breaking crop rings — is there prohibition concern? He wrote: slaughterers do wrong pressing thus on simanim between fingers — concern lest a ring jump and through the ring's point perforate the esophagus — one should protest; nevertheless b'dieved we do not establish prohibition, for severing the trachea in width in the majority is not a concern; and in length, even if only something remained above — kosher; all the more when skin is whole — no concern when no other presumption — see there.`,
});

// --- rabbi-akiva-eiger-yd (4) ---
patchFile('siman_024/rabbi-akiva-eiger-yd/part-001.txt', 'rabbi-akiva-eiger-yd', {
  '1#_': `(Siman 24, seif 11) If he inserted the knife under the first minority and slaughtered it from below upward — according to the first explanation of Rabbenu Tam, brought in Shach, s.k. 11: required under the knife under the first minority and he slaughtered the majority below it properly. Plainly it may deal with inserting in the first minority of the trachea — no concern from perforation — and he slaughtered the simanim in this haladah; and the wording "inserted in minority of simanim" may refer only to the trachea, as Rabbenu Tam explains the unresolved shehiyah in minority of simanim refers only to the esophagus. However, for the other explanation — this is Shulchan Aruch's law: inserted under the first minority and slaughtered it in haladah from below upward — this must be inserting in the first minority of the esophagus, for in the trachea first minority haladah does not harm; if so, inserting the knife may be like perforating the esophagus. I saw in Sefer HaYashar of Rabbenu Tam (siman 257) who wrote the first explanation above and wrote on it: for perforating the esophagus there is no concern — it is the manner of shechitah, as we are not concerned for kodashim under skin [should read: under skin because of blemish] — and this is very difficult: skin is different whether cutting from above or perforating; unlike simanim, where the manner of shechitah is required, and inserting the knife is mere perforation. More difficult: what compelled Rabbenu Tam to this — in the first explanation plainly inserting in first minority of trachea. And for the other explanation: since the essence of the unresolved matter is whether slaughtering the first minority in haladah invalidates — one may say the unresolved matter plainly: inserted under skin and cut a minority of simanim; and also on the side that under skin there is no haladah, we find inserting under the simanim and slaughtering first minority of esophagus from below upward. Later I found in Sefer HaMakri'a of Riaz (siman 5), who brought Rabbenu Tam's words in Sefer HaYashar and wondered greatly and raised that there is concern of perforating the esophagus; and incidentally I saw a wondrous matter there: what he refuted Rabbenu Tam's proof from under skin in kodashim — blemish of skin is not a blemish — from what we establish in Chatas HaOf and Chullin: flawed — if so, proven flawed is not a blemish in kodashim; if flawed were a blemish, because of outside slaughter he would not be obligated to bring inside. In my humble opinion this is wondrous: we rule there is no tumah and zav status in birds; with this there was room to resolve Tosafot's challenge, Chullin (daf 29b), s.v. kegon sheshachat, etc. — he is lashed for animal and flawed knife — see there: in an animal blemish disqualifies, it is not accepted inside.`,
  '2#_': `(Siman 24, Shach, s.k. 13) But certainly by law. In responsum of R' Yosef Migash (siman 41) he holds: by law shehiyah in the first minority of the trachea is forbidden — understand.`,
  '3#_': `(Seif 15 in the gloss) But while alive it is kosher, only shechitah does not help. Even in a bird: if one siman slipped and he slaughtered the second — it does not help, as the baraita teaches explicitly: found the crop dangling and unknown if before or after shechitah, etc. — the reason: nevertheless we require both simanim fit for shechitah — so Tosafot. However, according to Ramban, dangling is treifah, only when uprooted at the time of shechitah it is neveilah, for simanim sway [Shach, s.k. 24, brought thus — wondrous; I saw he stood on this in Peri Megadim]. One may say: truly in a bird, if he slaughtered one siman and the second was uprooted at shechitah — shechitah helps purify from neveilah, for the slaughtered siman was slaughtered well; and though the second uprooted siman is not fit for shechitah, from swaying one may say we do not require both simanim fit — for Ramban there is no proof from that baraita — for in any case forbidden from treifah law; nevertheless one may say not neveilah, like treifah that was slaughtered. And likewise perforated esophagus — we rule (siman 33) it is neveilah; nevertheless in a bird, perforated esophagus and he slaughtered the crop — one may say its disqualification in shechitah is not called, since the slaughtered siman has no disqualification — only like ordinary treifah that was slaughtered. With this, Rav Yonah's proof can be resolved: broken leg, unknown if while alive or after shechitah — forbidden from that baraita on dangling — meaning there in a bird it is not dangling doubt in shechitah, for shechitah was valid — only doubt of treifah.`,
  '4#_': `(Shach, s.k. 30) If the second reddens more — kosher. See siman 36, Shach, s.k. 12; and in Sefer Beit Efrayim, Sefat Emet, there.`,
});

// --- nekudot-hakesef (6) ---
patchFile('siman_024/nekudot-hakesef/part-001.txt', 'nekudot-hakesef', {
  '1#_': `(Siman 24, s.k. 1) On what Shach wrote in s.k. 4:`,
  '2#_': `(Gloss on Shulchan Aruch, seif 5) The entire spinal column — kosher. And even according to Rama in siman 67: l'chatchila one should be careful, etc.; however b'dieved kosher; and Beit Yosef wrote there in the name of Hagahot Alfasi: specifically breaking, for due to suffering it has no strength to suffer and expel blood; but cutting — no; only in the name of Rashba he wrote even cutting absorbs blood in limbs; and I saw where gentile butchers are the slaughterers, they cut the head from the animal's body immediately after shechitah; through this blood is absorbed in limbs; they do this so meat is heavy — they sell by weight; and also sell to Israelites — and according to Rashba one should protest; and see what I wrote below siman 67, seif 3 — end.`,
  '3#_': `(Taz, s.k. 2) But I greatly wondered, etc. In my humble opinion the verse teaches us that l'chatchila in every case it is forbidden even to eat from it not raw, as Shibbolei HaLeket wrote and Beit Yosef brought in siman 76, and Maharshal ruled, chapter Kol HaBasar, siman 99; or the verse teaches us that in kodashim even b'dieved forbidden — as Rashba's wording implies there: "but not the spinal column so blood is not absorbed in limbs; and in slaughter of kodashim blood is needed for sprinkling and throwing" — end; if so in non-sacred salting helps afterward only to remove its blood; but in kodashim what does salting afterward help? — this answer appears more correct.`,
  '4#_': `(Taz, s.k. 4) And it is difficult from Talmud Yerushalmi that it is not so, etc. In my humble opinion there haladah does not apply, since it had not yet come into the air of the world; or possibly this sugya is from the question: if you find to say under a cloth it is kosher, or perhaps it is different there, for the womb is like its house.`,
  '5#_': `(Gloss of the author's son on Shach, s.k. 18) Their words are forced, etc. — he meant: according to their words, Rambam deals with the esophagus; in the trachea, if he inserted the first third and completed properly — kosher, like half a defective trachea, as our elder grandfather wrote in s.k. 6; if so, where he inserted the first third, slaughtered the second third, inserted the last third — also kosher, for Rambam no disqualification applies in the last minority; if so why did he write it is invalid? Rather it must deal with the esophagus, and hagramah refers only to the trachea, for in the esophagus hagramah is in any amount; if so why did Rambam state generally, and wrote "where he inserted a third" — implies it refers to what he said above about hagramah, etc. — this is not so: hagramah deals with the trachea, and here with the esophagus; according to our grandfather's explanation, everything refers to the trachea — end.`,
  '6#_': `(Taz, s.k. 11) He challenged Bach and Hagahot Mahariu who invalidate any ikkur at shechitah from Tosafot and poskim — their words are not seen, for plainly we rule to declare treifah any ikkur at shechitah, as Rav Rama wrote in the gloss, and so is the world's sugya — obvious to all slaughterers; and from Tosafot and poskim there is no proof — they deal with law, as Shach wrote, s.k. 23; but we who practice to declare treifah all five laws of shechitah in any amount — plainly the same for ikkur; and so Mahariu wrote: ikkur is invalid whether in first minority, last minority, trachea, or esophagus — end; and so in other latter authorities.`,
});

// --- kaf-hachayim (20) ---
patchFile('siman_024/kaf-hachayim/part-001.txt', 'kaf-hachayim', {
  '1#_': `(a) [Seif 1] Darsah — how so, etc. The reason darsah is invalid: halacha leMoshe miSinai requires drawing and bringing the knife at shechitah; they relied on the verse "and slaughter" — "and slaughter" means "and draw" — Chullin 30b. Levush. Zivchei Tzedek, part 1, Chayei Adam, general rules 3, seif 3; and one who darsahes is like strangling, not like slaughtering, as Yair Netiv wrote and Kenesset HaGedolah brought in Hagahot Tur, part 1, Shulchan Gavoah, part 1.`,
  '2#_': `(b) There. Darsah — how so, such as placing the knife on the neck, etc. If while slaughtering the bird shakes its head in the middle of shechitah, or even at the end shakes head and body — Rav Dov Ber Katzenellenbogen, part 1, wrote to be stringent from concern for darsah; nevertheless he concluded: slaughterers and inspectors there said no one is concerned even for shaking in the middle without definite pause — common and never heard a question; and so Zivchei Tzedek, part 1 — in his country too they did not hear concern, only he wrote: nevertheless everything according to the instructor's eyes — if much strong shaking and he felt his hand left the neck entirely — forbid; everything according to the instructor — end; and sometimes the slaughterer is far toward the head and the neck lengthens toward the head; when the bird shakes its head it bends upward onto the knife at shechitah — haladah occurs — one must watch for this too; and see below, part 43.`,
  '3#_': `(c) And he wrote in Orach Tzedek, end of part 1: before bringing the knife to the neck, make drawing and bringing motions in the air so the moment the knife reaches the neck there is drawing and bringing — otherwise concern that on first contact it cuts somewhat of the esophagus without drawing and bringing — end; and Beit Din — Zivchei Tzedek, part 2, wrote: we heard thus practiced in Tiberias; in Baghdad they do not practice thus, for their knives are not so sharp to cut quickly — therefore they do not do so; nevertheless if one has a very sharp knife, he should do as in Eretz Yisrael; and since I saw it is not practiced and they do not distinguish sharp from not very sharp — therefore proper to be careful not to make the knife too sharp, from the above reason.`,
  '4#_': `(d) [Seif 2] If he slaughtered with holacha or hava'ah alone, if the knife has a full neck, etc. — nevertheless one need not draw that entire full neck beyond the neck — a person cannot be careful; this measure is only so he slaughters with ease; sometimes the knife is sharp and he slaughters most without drawing a full neck — only we are certain: since it has this measure, he can slaughter with ease. Tur in the name of his father Ra'osh. Peri Chadash, part 2; Peri To'ar, part 3; Zivchei Tzedek, part 2; Zivchei Tzedek, part 3.`,
  '5#_': `(e) However — even with a sharp knife, if it does not have a full neck and beyond the neck, and he drew and did not bring — even if known he did not darsah, the knife from sharpness slaughtered without darsah — nevertheless his shechitah is invalid. Peri Chadash there. She'eilot uTeshuvot, siman 8, part 3; Shulchan Petach, part 1; Zivchei Tzedek, part 3; Zivchat Shmuel, part 3, on laws of darsah.`,
  '6#_': `(f) There. If there is a full neck and beyond the neck, etc. — kosher; if not, invalid; and even if he began at the knife head and drew the entire knife over the entire neck to the handle — invalid. Peri To'ar, part 4; Zivchei Tzedek, part 5.`,
  '7#_': `(g) A knife with two necks' measure slaughtering simanim with holacha or hava'ah alone — kosher; but if he removed the entire head with holacha or hava'ah alone, this measure of a full neck beyond the neck does not suffice. Peri Chadash, part 1; and Turei Zahav, end of siman 8, agreed — specifically in an animal, because Rashba wrote spinal bone is hard — not in a bird — see there; but Maharach Kazis in Chok L'Yisrael agreed to validate; and so appears Rambam, chapter 2, and Ramban, and Rashba's responsum, siman 17, and Socher Hashem understood — no distinction between bird and animal — see there. Erech HaShulchan, part 1; and Rav Zivchei Tzedek, part 6, agreed: no distinction; also removing entire head with holacha or hava'ah suffices with neck measure and full neck beyond — see there; and see below, seif 5, and our words there.`,
  '8#_': `(h) L'chatchila — the slaughterer must slaughter with holacha and hava'ah even if the knife is long as several necks. Tosefet Chaim on his Chullin, daf 30; and Peri Chadash, part 3, agreed; She'eilot uTeshuvot, siman 8, part 3; Shulchan Petach, part 2; Chayei Adam, general rules 3, part 3; Kometz, part 3; Ahel Yitzchak, siman 6, part 2; Zivchei Riv, siman 5, on temidim, part 5; Minchat Yitzchak, part 3; Zivchei Tzedek, part 7.`,
  '9#_': `(i) From here clear rebuke to some slaughterers who show dexterity: with great speed and ease they pass the knife on the bird's neck with drawing alone or bringing, and mostly with a small part of the knife they slaughter the simanim — l'chatchila they do thus to show strength in the craft — clearly invalid shechitah; not to mention l'chatchila they should not do so, for at least they must pass the entire knife over the simanim in this measure the sages established as if he drew and brought; but if he slaughters with a small knife part, and quickly — impossible to avoid darsah concern; certainly the end is he did not do this alone but from lack of fear of Heaven and wishes to show strength before other slaughterers; possibly even b'dieved we concern for this shechitah; and whoever eats this shechitah besides eating safek darsah further supports sinners by seeing their deeds are beloved to people — they increase and boast, thinking they act properly — therefore their sin is too great to bear. Kesef Acher, chapter 2 of five chapters of shechitah, law 9; and Rav wrote in Mikhtav Eliyahu: I know in my youth I practiced thus and thought nothing higher; from the day I was chosen in Zolkiew community and tried before the Rav and those before him to slaughter birds before them with drawing alone — they rebuked me — heaven forbid to do so again — only with drawing and bringing as Shulchan Aruch implies — end; and Beit Din — Esheron, part 8, wrote: whoever transgresses their words — better he had not been created; Zivchei Tzedek, part 8 — therefore be careful not to make bird knives too sharp.`,
  '10#_': `(j) That which they said: if the knife has two necks in what is slaughtered — kosher with holacha or hava'ah alone — if he begins from the knife head intending to draw or bring its entire length — then even if from sharpness it slaughtered one full neck — kosher; but if he began in part of the knife, from that part onward there must be two necks' measure from there; and if he intended not to draw or bring the entire knife, only until some point — from the start until that stopping point there must be two necks' measure. She'eilot uTeshuvot, part 2; Kometz, part 4; Ahel Yitzchak, siman 6, in Leket Yosher, part 2; Zivchei Riv, siman 5, on temidim, part 7; Minchat Yitzchak, part 3; Zivchei Tzedek, part 10.`,
  '11#_': `(k) And the measure of two necks — in bird and animal; do not think: I have fourteen finger-widths in the knife, though the neck is wide, it reaches two necks since he draws and brings — enough even more beyond the neck; as I heard from an expert boasting he can slaughter calves with a bird knife — they do wrong: when the knife is short it slips into the slaughter-house mid-shechitah — comes to darsah, shehiyah, and ikkur — therefore measure for each species two necks with skin and spinal column. Minchat Yitzchak, in Leket Yosher, part 7.`,
  '12#_': `(l) There, gloss. And some are stringent in an animal — for they hold it was said only in a bird whose neck is thin. Biur HaGra, part 2; and see above siman 8, part 2.`,
  '13#_': `(m) There, gloss. And some are stringent in an animal — since its neck is hard and the knife small, it comes under darsah. Kereti, part 2.`,
  '14#_': `(n) There, gloss. And the custom in these provinces to invalidate an animal, etc. — likewise rule practically everywhere; especially nowadays we are not accustomed to slaughter with such a small knife. She'eilot uTeshuvot, siman 8, part 4; especially nowadays.`,
  '15#_': `(o) [Seif 3] Slaughtered two heads as one, etc. — this law is uncommon among us; nowadays we never heard two heads slaughtered as one — therefore we did not write on this.`,
  '16#_': `(p) [Seif 4] Two hold the knife and slaughter, etc. — this law too is not found among us; we never heard or saw anyone do this.`,
  '17#_': `(q) [Seif 5] He was slaughtering and cut the entire spinal column — kosher. Its law is like breaking the animal's spinal column, stated below siman 67, seif 3 — see there; and so Rashba in Tur HaDeshen and Mishmeret HaBayit, daf 23 — see there; Peri Chadash, part 7; Zivchei Tzedek, part 9.`,
  '18#_': `(r) There, gloss. And the custom to declare treifah even if only majority, etc. — however Shach, s.k. 5, brought many great poskim and from the Gemara that it is permitted; and wrote: study on our master's words; and concluded: perhaps the Rav in the gloss was stringent specifically where there is no great loss — and in such a case. So too Chayei Adam, general rules 7, part 8; and Peri Chadash, part 8, wrote: even in small loss the lenient did not lose; and Beit Yisrael, part 2, wrote: now slaughterers declare treifah even in great loss; and so by experience. She'eilot uTeshuvot, part 5; and in these countries (Ashkenaz) they practice to forbid, not even lenient in great loss; even without intent. And Kenesset HaGedolah in Hagahot Beit Yosef, end of part 17, wrote: we do not practice thus — many birds are slaughtered with majority of spinal column and we do not invalidate; and so Shulchan Gavoah, part 7 — except their custom validates even if entire head was cut. And so Turei Zahav, siman 91, part 6; and Rav Zivchei Tzedek, part 14, wrote: in Baghdad, if majority of spinal column was cut they validate; but if entire spinal column cut and not even a thread remained — they practice treifah; except in great loss or mitzvah need one may be lenient even if entire spinal column cut. It turns out customs differ; and Peri To'ar, part 8, wrote: where they practiced to forbid, they practiced like permitted matters, etc.; where they did not practice — do not practice; all who slaughtered with holacha and hava'ah — end.`,
  '19#_': `(s) And in countries where custom was not clarified — if he intended thus in his slaughter, do not be lenient except in great loss; but if he did not intend and the spinal column was also cut — do not forbid at all. She'eilot uTeshuvot, there.`,
  '20#_': `(t) There, gloss. Even if he only cut majority of spinal column — meaning majority of the cord within the spinal column. Taz, s.k. 2. She'eilot uTeshuvot, part 5; Kometz, part 7; Minchat Yitzchak, part 5.`,
});

// --- yad-avraham (1) ---
patchFile('siman_024/yad-avraham/part-001.txt', 'yad-avraham', {
  '1#_': `(Siman 24, seif 10) If after he slaughtered the majority of the simanim he inserted the knife under the minority remaining of both or one of them and paused — permitted; and there is one who forbids in this too, and fitting to heed l'chatchila — meaning Ra'osh's view; and Ribbi's view: in shehiyah, darsah, and haladah, which are the manner of shechitah and in the place of shechitah, forbid in the last minority; but in hagramah and ikkur, not in the place of shechitah and not the manner of shechitah — do not forbid in the last minority; and Ra'osh wrote thus seems correct; therefore in hagramah, seif 12, and ikkur, seif 15, Shulchan Aruch did not bring "there is one who forbids"; see Shach, s.k. 16. In my humble opinion, Ra'osh and Ribbi did not forbid all haladah, only haladah slaughtering from above downward — such as inserting between both minorities and slaughtering the lower properly from above downward; or possibly he did not insert between them at all, only slaughtered under a cloth stuck to its neck, as seif 8; but in haladah Shulchan Aruch mentioned here — inserted under minority and paused — meaning from below upward — on this Ra'osh and Ribbi did not forbid, for from below upward is not the manner of shechitah, as explicit in the sugya and Rashi, chapter HaShochet (daf 30b), Rif, Ra'osh, and Shulchan Petach; and behold in ikkur, since not the manner of shechitah, they did not forbid; and the same for haladah from below upward — not the manner of shechitah — they did not forbid in the last minority. Therefore Shulchan Aruch's words are difficult — why bring "there is one who forbids" here and not in hagramah and ikkur.`,
});

// --- yad-ephraim (3) ---
patchFile('siman_024/yad-ephraim/part-001.txt', 'yad-ephraim', {
  '1#_': `And if not, there is concern to forbid both. See Ba'er Heitev; and he wrote in Shevut Yaakov, part 3, siman 60: a slaughterer who slaughters with both hands, with holacha and hava'ah — there is no concern of darsah.`,
  '2#_': `And there is one who invalidates in this too. See Ba'er Heitev; and see in Shevut Yaakov what he wrote on Shulchan Aruch's words, siman 14 in the gloss; and he brought there Tosafot, Beitzah: it implies since the Merciful One validated four simanim, Rav Oshaya's question applies only l'chatchila — forbidden to do so, like slaughtering at night — see there.`,
  '3#_': `Nevertheless one should not deviate. See Ba'er Heitev; and he wrote in Shevut Yaakov, part 1, siman 46, on what Taz, siman 24, s.k. 17, wrote on a ring found on the knife — to validate from safek safeka, though Taz himself holds in established prohibition safek safeka does not help — nevertheless here he relies to be lenient because Agur and Beit Yosef, etc.; and though Shach implies like the stringent — since in Nekudot HaKesef he did not challenge, etc.; and see in Be'er HaGolah, siman 122, he tends to be stringent but not compelled; the lenient like Taz here did not lose — see there; and see Shevut Yaakov, part 2, siman 55: he practiced treifah for a whole ring on the knife; on the ground, validate in great loss, mitzvah need, Shabbat honor, or guest honor; if the ring was cut in the middle and hangs on the trachea, or rests or hangs in the middle on knife or ground — do not be stringent; he received from an expert slaughterer: to avoid crop-ring doubt common in geese, slaughter pen-slanted obliquely — then proven no ring in their slaughter — end. And in She'eilat Ya'avetz, part 2, siman 237, on a slaughterer who slaughtered a goose and found a crop-ring piece on the knife — pressed on his face to permit: Rama and followers to be stringent only on a whole ring, for one can suspect and attribute to pushing before shechitah; but here the crop and ring were cut through the width into two — clearly evident it could not be before shechitah — impossible to uproot without shechitah; especially a straight cut like this — no suspicion of pushing before shechitah as latter authorities fear when not whole width but a thin strip; not all aspects equal — all agree to permit; whoever is stringent after examination that it is not a whole-width ring but only a thin strip is among the astonished, etc.; and so my obligation: stuck in the knife or glued on his face and fell to ground — all one matter with clear proof the ring was entirely slaughtered; a fortiori from Taz's law, etc.; therefore he only doubted partial cut — not whole — certainly slaughtered — see there.`,
});

